(121650, 'frFR', '<Acquérir Maîtrise des lignes telluriques pour 10 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t mana ancestral.>', '<Acquérir Maîtrise des lignes telluriques pour 10 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t mana ancestral.>', 25549),
(121649, 'frFR', '<Acquérir Maîtrise des lignes telluriques pour 20 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t mana ancestral.>', '<Acquérir Maîtrise des lignes telluriques pour 20 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t mana ancestral.>', 25549),
