(116747, 'frFR', 'Vous percevez la présence d’une importante réserve d’énergie tellurique non loin.', 'Vous percevez la présence d’une importante réserve d’énergie tellurique non loin.', 25549),
(116746, 'frFR', 'Il y a tant d’amis avec qui se divertir, ici !', 'Il y a tant d’amis avec qui se divertir, ici !', 25549),
(116745, 'frFR', 'Vous vous sentez chez vous.', 'Vous vous sentez chez vous.', 25549),
(116744, 'frFR', 'Ces cristaux sont vraiment énormes !', 'Ces cristaux sont vraiment énormes !', 25549),
(116743, 'frFR', 'Vous avez la sensation que d’immenses bâtiments se dressent au-dessus de vous.', 'Vous avez la sensation que d’immenses bâtiments se dressent au-dessus de vous.', 25549),
(116742, 'frFR', 'Vous sentez non loin la présence d’une déchirure dans la trame de la magie.', 'Vous sentez non loin la présence d’une déchirure dans la trame de la magie.', 25549),
(116741, 'frFR', 'L’énergie tellurique semble vous nimber.', 'L’énergie tellurique semble vous nimber.', 25549),
(116740, 'frFR', 'Il y a vraiment de très beaux cristaux, ici !', 'Il y a vraiment de très beaux cristaux, ici !', 25549),
(116739, 'frFR', 'Vous ressentez une révulsion mêlée de pitié pour ces créatures.', 'Vous ressentez une révulsion mêlée de pitié pour ces créatures.', 25549),
(116738, 'frFR', 'Vous entendez ruisseler une grande cascade à proximité.', 'Vous entendez ruisseler une grande cascade à proximité.', 25549),
