UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Varian vous a $genvoyé:envoyée; aussi ? Nous sommes en infériorité numérique dans ma propre ville !$b$b<Les yeux de Jaina lancent des éclairs.>$b$bTournons les choses autrement et mettez-vous à ma place. Imaginez que VOUS êtes à la tête du Kirin Tor. $p ! L’archimage le plus influent de tout Azeroth !$b$bQue feriez-VOUS ?', `VerifiedBuild`=25549 WHERE (`ID`=70169 AND `locale`='frFR');
