UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les mogu sont imbus d’eux-mêmes, arrogants et puissants. Des traits de caractère qui mettront Garrosh dans une rage folle dès qu’il les verra.\n\nC’est la raison pour laquelle il est capital que nous capturions et interrogions leur chef avant que cela se produise.', `VerifiedBuild`=25549 WHERE (`ID`=69973 AND `locale`='frFR');
