UPDATE `broadcast_text_locale` SET `MaleText_lang`='Et qu’adviendra-t-il quand nos guerres seront terminées ? Pensez-vous pouvoir retourner à la vie civile sans problème, malgré les horreurs auxquelles vous avez assisté ?', `VerifiedBuild`=25549 WHERE (`ID`=66744 AND `locale`='frFR');
