UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Ouah, c’est incroyable ! Regarde toutes ces lumières !$b$bÀ ton avis, il se passe quoi ? Et le type sur la tortue, c’est qui ?$b$bAh mais atteeends, c’est Liu Lang, non ?$b$bEt la tortue, ce doit être Shen Zin Su. C’est ça ! C’est une statue d’une toute petite île Vagabonde !$b$bOn est chez nous, oncle Chen !$b$bEnfin, presque.', `VerifiedBuild`=25549 WHERE (`ID`=65954 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai une vraie surprise pour vous. À votre avis, qu’est-ce qu’ils fêtent ? Et quelle sera la bonne boisson pour l’occasion ?', `VerifiedBuild`=25549 WHERE (`ID`=65953 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='$n ! Je suis ravi de voir que vous célébrez le festival de l’explorateur avec nous !$b$bOn entend souvent dire que les pandarens ne sont pas aventureux. Mais regardez donc tous ces visages… vous voyez ? Ils ont le regard étoilé de tous les rêveurs !$b$bJe suis sûr qu’un jour, il y aura encore plus d’aventuriers pandarens qui feront de grandes choses partout dans le monde. Vous ne pensez pas ?', `VerifiedBuild`=25549 WHERE (`ID`=65952 AND `locale`='frFR');
