UPDATE `broadcast_text_locale` SET `MaleText_lang`='C’est très étrange. Les pandashan sont nos meilleurs clients. Nous leur vendons des provisions, et ils assurent notre sécurité.$b$bPourquoi ne nous laissent-ils pas entrer ? Je ne comprends pas.', `VerifiedBuild`=25549 WHERE (`ID`=65630 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=65629 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai perdu le yack sur chemin d’ici. Vraiment pas bien.', `VerifiedBuild`=25549 WHERE (`ID`=65628 AND `locale`='frFR');
