UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous avons fait voyage à travers hozen méchants, yétis affamés, yacks puants. Et maintenant, pandashan parlent comme si nous étions étrangers.$b$bC’est très mauvaise fortune.', `VerifiedBuild`=25549 WHERE (`ID`=65626 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=65625 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pandashan ont toujours été amis des grumelots. Pourquoi ne veulent plus qu’on entre ?', `VerifiedBuild`=25549 WHERE (`ID`=65624 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une fin honorable pour le noble Maki… Je suis sûr que son clan serait fier de lui, s’il existait encore !', `VerifiedBuild`=25549 WHERE (`ID`=65623 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Est-ce que vous pourriez la chanter à nouveau, pour les élèves qui viennent d’arriver ?', `VerifiedBuild`=25549 WHERE (`ID`=65622 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Merci, Ruolin ! C’était très beau.', `VerifiedBuild`=25549 WHERE (`ID`=65621 AND `locale`='frFR');
