UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Et je crois qu’il a très bien vécu la sienne. Tout ce que nous avons, nous le devons à Liu Lang, le premier explorateur pandaren.', `VerifiedBuild`=25549 WHERE (`ID`=65619 AND `locale`='frFR');
