UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=62831 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ah, mais vous n’êtes pas étranger à votre passé ! Originaire de l’île Vagabonde. Je dois admettre que je pensais que votre patrie n’était qu’une légende. Les pandarens de l’île sont bien plus aventureux que ceux du continent… vous avez ça dans le sang !', `VerifiedBuild`=25549 WHERE (`ID`=62830 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Et bien… c’est intéressant. La plupart de vos ancêtres sont morts dans un incendie. Bigre. Votre peuple prend des risques importants au nom du progrès ! J’aimerais qu’un plus grand nombre de pandarens aient votre esprit d’initiative.', `VerifiedBuild`=25549 WHERE (`ID`=62829 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ah, vous êtes d’un noble lignage ! Votre peuple disposait d’une IMMENSE puissance, et des terribles fardeaux que cela entraîne. Vos souffrances aussi ont été immenses. Je comprends maintenant pourquoi vous avez pris ce nom d’elfes « de sang. »', `VerifiedBuild`=25549 WHERE (`ID`=62828 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Incroyable… comme je le soupçonnais. Votre histoire remonte à l’aube du monde. Les empires des trolls y étaient gigantesques. Je vois une étincelle dans vos yeux, une volonté puissante… Vous aimeriez recouvrer cette grandeur, non ?', `VerifiedBuild`=25549 WHERE (`ID`=62827 AND `locale`='frFR');
