UPDATE `broadcast_text_locale` SET `MaleText_lang`='Comme c’est fascinant. Je vous trouvais un air un peu maladif… mais je vois maintenant la vérité. Votre peuple est sous le joug de terribles ténèbres. Quelle force vous devez avoir, simplement pour poursuivre votre existence !', `VerifiedBuild`=25549 WHERE (`ID`=62825 AND `locale`='frFR');
