UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez les anciennes chariottes à vapeur ?$b$bNous en avons de toutes nouvelles pour vous.$b$bNormalement, il vous en coûterait deux jetons pour utiliser une télécommande de chariotte. Mais en raison de vos états de service, vous avez droit à une réduction d’un jeton.$b$bÀ la foire de Sombrelune, nous vous remercions de remplir votre devoir.', `FemaleText_lang`='Vous cherchez les anciennes chariottes à vapeur ?$b$bNous en avons de toutes nouvelles pour vous.$b$bNormalement, il vous en coûterait deux jetons pour utiliser une télécommande de chariotte. Mais en raison de vos états de service, vous avez droit à une réduction d’un jeton.$b$bÀ la foire de Sombrelune, nous vous remercions de remplir votre devoir.', `VerifiedBuild`=25549 WHERE (`ID`=53059 AND `locale`='frFR');
