UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Ne bouge pas, mon amour. Calme ton esprit. Tu es devenu l’esclave du devoir. Mais c’est en restant fidèle à ton cœur que tu rempliras tes obligations… envers ton peuple… et envers moi. Il n’en sera pas autrement.', `VerifiedBuild`=25549 WHERE (`ID`=52112 AND `locale`='frFR');
