UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Tu es Go’el, fils de Durotan et de Draka ! Chef légitime de la Horde ! Tu es l’orc qui a gagné mon cœur ! Rappelle-toi QUI TU ES !', `VerifiedBuild`=25549 WHERE (`ID`=52110 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je connais ton visage… Aggra ! Oh, mon cœur… tu ne vois pas ? Je ne suis… plus rien. Égoïste… j’ai tout fait… accompli… seulement par ORGUEIL. Je suis… indigne de toi…', `VerifiedBuild`=25549 WHERE (`ID`=52109 AND `locale`='frFR');
