UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Tu as fait ce que tu pensais juste, Go’el ! Combats ces doutes ! Ils dévorent ton cœur !', `VerifiedBuild`=25549 WHERE (`ID`=52106 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai… perdu la Horde… en tant que chef… Garrosh… la mène à sa perte… Mon peuple… à sa perte. Cairne, mon frère… pourquoi ne t’ai-je pas écouté ?', `VerifiedBuild`=25549 WHERE (`ID`=52105 AND `locale`='frFR');
