UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je préférais les worgens quand ils étaient assez désorganisés pour qu’on ne les croise qu’en petites meutes. Cette nouvelle alliance des worgens gilnéens est beaucoup moins facile à manier.', `VerifiedBuild`=25549 WHERE (`ID`=48714 AND `locale`='frFR');
