UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il serait en train de forger un artéfact, une arme, avec la puissance d’un Dieu très ancien. Nous ne savons pas exactement ce que c’est, mais il faut nous en emparer avant que Cho’gall ne la termine.$B$BTout le reste est secondaire. Tout le monde est sacrifiable, y compris vous et moi.', `VerifiedBuild`=25549 WHERE (`ID`=46319 AND `locale`='frFR');
