UPDATE `broadcast_text_locale` SET `MaleText_lang`='HA ! Tu ne nous reconnais pas, Dempsey ? C’est Godfrey. Et voici le seigneur Walden et le baron Ashbury. Alors, nous te « sauvons », et voilà comment tu nous remercies ?', `VerifiedBuild`=25549 WHERE (`ID`=46043 AND `locale`='frFR');
