UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis plus qu’un Réprouvé… plus qu’un homme… Je suis… quelque chose de nouveau. Quelque chose… de différent.', `VerifiedBuild`=25549 WHERE (`ID`=46040 AND `locale`='frFR');
