UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis en train de perdre la raison. Je n’arrive pas à rassembler mes pensées…', `VerifiedBuild`=25549 WHERE (`ID`=46037 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Faites court. Je ne suis pas d’humeur aux jérémiades ou aux délires.', `VerifiedBuild`=25549 WHERE (`ID`=46036 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai toujours adoré les Pins-Argentés… jusqu’à ce que le roi-liche y lâche les armées enragées du Fléau et ne transforme la forêt en une énorme fosse commune pourrissante. Maintenant, sa simple vue me mortifie. Haha.', `VerifiedBuild`=25549 WHERE (`ID`=46035 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=46034 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Et j’ai gardé le meilleur pour la fin : je ressens désormais une faim insatiable de la chair des autres humanoïdes. Dévorer leurs cadavres me rend plus fort. Hum, tout simplement DÉLICIEUX.', `VerifiedBuild`=25549 WHERE (`ID`=46033 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oh, et maintenant les effets de contrôle mental n’ont quasiment plus aucun effet sur moi. PARCE QUE JE N’AI PLUS DE CERVEAU !', `VerifiedBuild`=25549 WHERE (`ID`=46032 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Être un Réprouvé a ses bons côtés. Voyons… Je peux quasiment vivre sous l’eau. Je peux rester immergé 233%% plus longtemps que ces mortels pleins de chair. Oui, 233%%, faites le compte.', `VerifiedBuild`=25549 WHERE (`ID`=46031 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=46030 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Non, Godfrey, je n’ai pas été l’artisan de ma propre contamination. C’était un « don », tu te souviens ? Alors maintenant, profite bien de ce « don » et ferme-la.', `VerifiedBuild`=25549 WHERE (`ID`=46029 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=46028 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Gilnéas était un rêve inaccessible. Seul un homme doué d’une vraie vision pourrait l’avoir réalisé… Mais Grisetête ? Jamais…', `VerifiedBuild`=25549 WHERE (`ID`=46027 AND `locale`='frFR');
