UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai réussi !$B$BÀ partir de saphir prélevé sur les décorations de la chambre, j’ai fabriqué des lunettes qui me permettent de voir des choses… merveilleuses !$B$B$B$BAvec un peu de chance, c’est en tant qu’homme riche que j’écrirai la prochaine entrée !', `VerifiedBuild`=25549 WHERE (`ID`=45962 AND `locale`='frFR');
