UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il m’a fallu toute la journée pour déchiffrer la formule donnée par ces hiéroglyphes :$B$B$B Par le bleu des yeux, la lueur de la lune$Bse révèle.$B$B Dix éclats, le bâton, et le voile$Bdisparaît.$B$BAu diable Schnottz et ses promesses en l’air !$B$BSi j’arrive à percer cette énigme, tous ses secrets m’appartiendront !', `VerifiedBuild`=25549 WHERE (`ID`=45960 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une belle journée bien productive !$B$BLa chambre est effectivement ancienne, et elle abrite un magnifique mécanisme qui semble ne plus fonctionner.$B$BJe vais regarder ça de plus près demain.$B$BCette découverte va sûrement obliger Schnottz à me remarquer !$B$BComment est-ce qu’il pourrait me refuser une promotion après un tel résultat !', `VerifiedBuild`=25549 WHERE (`ID`=45959 AND `locale`='frFR');
