UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il faudra peut-être un certain temps pour reconstruire et nettoyer Stratholme, mais c’est un travail que j’aurai beaucoup de plaisir à observer à l’œuvre. Peut-être verrons-nous un jour un prochain grand défenseur de la Lumière ordonné dans le bastion de la Main d’argent, ou dans la chapelle d’Alonsus. Et quel que soit l’avenir, notre travail ici portera de beaux fruits.', `VerifiedBuild`=25549 WHERE (`ID`=45608 AND `locale`='frFR');
