UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les vendeurs liés à une profession précise s’installent toujours près de leurs maîtres respectifs. Les autres types de vendeurs sont un peu partout dans la ville.$B$BQu’est-ce que vous cherchez ?', `FemaleText_lang`='Les vendeurs liés à une profession précise s’installent toujours près de leurs maîtres respectifs. Les autres types de vendeurs sont un peu partout dans la ville.$B$BQu’est-ce que vous cherchez ?', `VerifiedBuild`=25549 WHERE (`ID`=44651 AND `locale`='frFR');
