UPDATE `broadcast_text_locale` SET `MaleText_lang`='La prison ? Mais qu’est-ce qui pourrait vous intéresser là-bas ? Elle est au centre de la ville, juste au nord-est du quartier des Mages.$B$BSi vous y allez vraiment, faites attention. Il y a des rumeurs de révolte.', `FemaleText_lang`='La prison ? Mais qu’est-ce qui pourrait vous intéresser là-bas ? Elle est au centre de la ville, juste au nord-est du quartier des Mages.$B$BSi vous y allez vraiment, faites attention. Il y a des rumeurs de révolte.', `VerifiedBuild`=25549 WHERE (`ID`=44640 AND `locale`='frFR');
