UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai envoyé mon garçon au bosquet de Thal’darah pour rapporter des preuves. Vous verrez bientôt qu’il n’y a aucune menace.', `VerifiedBuild`=25549 WHERE (`ID`=41946 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='De plus, je suis ici par ordre du suzerain Krom’gar, lui-même commissionné par notre chef de guerre, Garrosh Hurlenfer. Vous obéirez, ou vous en subirez les conséquences.', `VerifiedBuild`=25549 WHERE (`ID`=41945 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mes éclaireurs m’ont rapporté que ce bosquet abrite une puissante arme. Une arme que l’Alliance utilisera contre nous si on ne fait rien pour l’arrêter.', `VerifiedBuild`=25549 WHERE (`ID`=41944 AND `locale`='frFR');
