UPDATE `broadcast_text_locale` SET `MaleText_lang`='Tout ce que vous trouvez au bosquet de Thal’darah, ce sont des jeunes druides complètement terrifiés. Ils n’ont pas d’armes de destruction massive.', `VerifiedBuild`=25549 WHERE (`ID`=41941 AND `locale`='frFR');
