UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mettez une paume sur votre cœur et tendez l’autre main vers l’infini. Est-ce que l’infini est tendre ? NON ! Il est... immense.', `FemaleText_lang`='Mettez une paume sur votre cœur et tendez l’autre main vers l’infini. Est-ce que l’infini est tendre ? NON ! Il est... immense.', `VerifiedBuild`=25549 WHERE (`ID`=40206 AND `locale`='frFR');
