UPDATE `broadcast_text_locale` SET `MaleText_lang`='Et où est votre maître maintenant, Corne-Noire ? Il n’est pas trop tard pour revenir vers la lumière...', `FemaleText_lang`='Et où est votre maître maintenant, Corne-Noire ? Il n’est pas trop tard pour revenir vers la lumière...', `VerifiedBuild`=25549 WHERE (`ID`=40019 AND `locale`='frFR');
