UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous avez une idée du temps et du flouze que vous nous avez permis d’économiser, $n ? Tout ça aurait pu être un désastre complet, et vous avez sauvé tout le cartel à vous $gtout seul:toute seule;.$B$BDommage que Thrall et vous ayez épargné Gallywix. Je pense que vous auriez fait $gun parfait prince marchand:une parfaite princesse marchande; !', `VerifiedBuild`=25549 WHERE (`ID`=39622 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je sais que vous aviez l’étoffe pour nous sauver la peau verte, $n !$B$BEt maintenant, on se tire d’ici avant que je sois obligé de tuer Bulle et Doigt.', `VerifiedBuild`=25549 WHERE (`ID`=39621 AND `locale`='frFR');
