UPDATE `broadcast_text_locale` SET `MaleText_lang`='Toi t’es pas mon chef de guerre à moi. Mon respect, tu l’as pas mérité, et la Horde, je la laisserai pas détruire pour ta stupide envie de guerre.', `VerifiedBuild`=25549 WHERE (`ID`=38899 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Y’a pas de pourquoi, Garrosh. Si le titre, tu l’as eu, c’est que t’es le fils de Grom et que les gens ils veulent un héros de la guerre.', `VerifiedBuild`=25549 WHERE (`ID`=38898 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ne me reprends pas, troll. Tu sais qui a reçu le commandement. Tu n’as pas compris pourquoi c’est moi et pas toi que Thrall a choisi ?', `VerifiedBuild`=25549 WHERE (`ID`=38897 AND `locale`='frFR');
