UPDATE `broadcast_text_locale` SET `MaleText_lang`='Thrall, ses paroles elles sont vraies, comme toujours. La Horde, elle est beaucoup plus que des vieux chefs têtus et une poignée de héros du Norfendre. Les gens ils crient le nom de Garrosh... Pour l’instant, au moins.', `VerifiedBuild`=25549 WHERE (`ID`=38890 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=38889 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Throm’ka, mon vieil ami.', `VerifiedBuild`=25549 WHERE (`ID`=38888 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=38887 AND `locale`='frFR');
