UPDATE `broadcast_text_locale` SET `MaleText_lang`='La Horde a besoin d’un héros du passé. Un orc au sang pur qui ne ploiera pas devant les humains et qui ne tolèrera aucune traîtrise. Un guerrier qui rendra à notre peuple sa fierté. Et ça peut être Garrosh.', `VerifiedBuild`=25549 WHERE (`ID`=38884 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Malgré ma prétendue sagesse, je n’ai pas toujours réussi à fédérer la Horde. Les évènements du portail du Courroux et de Fossoyeuse l’ont prouvé.', `VerifiedBuild`=25549 WHERE (`ID`=38883 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ton conseil, je dois l’avoir, mon ami. Garrosh, je peux pas rester avec lui quand il nous tourne les uns contre les autres pour la guerre. Mon respect pour toi, il est plus dans cette nouvelle Horde... Mon peuple, j’ai peur qu’il doive partir ailleurs.', `VerifiedBuild`=25549 WHERE (`ID`=38882 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vol’jin, j’ai nommé Garrosh car il a la force de guider notre peuple en ces temps troublés.', `VerifiedBuild`=25549 WHERE (`ID`=38881 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=38880 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='En effet. On a essayé de me tuer, mais c’est le cadet de mes soucis pour l’instant. Le monde lui-même a besoin de mon aide.', `VerifiedBuild`=25549 WHERE (`ID`=38879 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Garrosh, j’ai pas d’amour pour lui, ça c’est sûr. Mais la Horde, faut pas la quitter sur un coup de tête.', `VerifiedBuild`=25549 WHERE (`ID`=38878 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les réponses, il y en a qu’un qui les connaît. Vous pouvez rester et observer.', `VerifiedBuild`=25549 WHERE (`ID`=38877 AND `locale`='frFR');
