UPDATE `broadcast_text_locale` SET `MaleText_lang`='Peut-être, $c, peut-être.$B$BMais si vous souhaitez vous lancer dans cette quête vous-même, il vous faudra suivre l’enseignement des maîtres de forge du Verdict des cendres.$B$BCollaborez avec eux, et démontrez votre loyauté et votre dévouement.$B$BQuand ce sera fait, nous pourrons rediscuter de tout ça.', `VerifiedBuild`=25549 WHERE (`ID`=37192 AND `locale`='frFR');
