UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je réfléchis à cette question sans arrêt.$B$BJe pense qu’il serait possible de forger une arme capable d’égaler la puissance de Deuillegivre sans réduire son maître en esclavage.$B$BMais oubliez, $r. Même si c’était possible, nous n’avons pas le temps de fabriquer un tel objet.$B$BIl vaut mieux concentrer votre énergie sur notre assaut.', `VerifiedBuild`=25549 WHERE (`ID`=37187 AND `locale`='frFR');
