UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous avons envoyé une troupe de chevaliers capturer deux lieutenants du Fléau d’Arthas pour représenter le prochain défi du tournoi. Ils n’ont pas encore rapporté leurs proies, la prochaine phase du tournoi est donc en attente. Revenez voir la semaine prochaine.', `VerifiedBuild`=25549 WHERE (`ID`=36088 AND `locale`='frFR');
