UPDATE `broadcast_text_locale` SET `MaleText_lang`='Un vrai croisé est plus qu’un simple héros de la guerre contre le mal… Un vrai croisé est un exemple, un champion aux yeux de tout son peuple qui rallie les gens à sa cause.$B$BIl est de mon devoir de Haut croisé de confier des quêtes dignes de leur rang à de tels personnages.', `VerifiedBuild`=25549 WHERE (`ID`=35142 AND `locale`='frFR');
