UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=35095 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le niveau de logistique qu’implique une célébration optimale des Bienfaits du pèlerin est tout bonnement époustoublifiant ! Toutes ces matières premières, tout ce travail, des milliers et des milliers de caisses de produits de consommation expédiés ici et là et partout pour des tables des Bienfaits à n’en plus compter...$B$BHonnêtement, moi je suis impressionné ! Et affamé, aussi... Ça sent la tarte à la citrouille. Vous sentez aussi ?', `FemaleText_lang`='Le niveau de logistique qu’implique une célébration optimale des Bienfaits du pèlerin est tout bonnement époustoublifiant ! Toutes ces matières premières, tout ce travail, des milliers et des milliers de caisses de produits de consommation expédiés ici et là et partout pour des tables des Bienfaits à n’en plus compter...$B$BHonnêtement, moi je suis impressionnée ! Et affamée, aussi... Ça sent la tarte à la citrouille. Vous sentez aussi ?', `VerifiedBuild`=25549 WHERE (`ID`=35094 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les humains sont pas fichus d’brasser grand-chose à part l’air, mais bon sang, cuisiner, ça ils savent faire ! Les Bienfaits ? Et plutôt deux fois qu’une !', `FemaleText_lang`='Les humains sont pas fichus d’brasser grand-chose à part l’air, mais bon sang, cuisiner, ça ils savent faire ! Les Bienfaits ? Et plutôt deux fois qu’une !', `VerifiedBuild`=25549 WHERE (`ID`=35093 AND `locale`='frFR');
