UPDATE `broadcast_text_locale` SET `FemaleText_lang`='On dit souvent que c’est avant l’aube que la nuit est la plus noire. Mais l’aube viendra, Tahu. Le soleil se lèvera. L’harmonie retournera là où elle doit être.', `VerifiedBuild`=25549 WHERE (`ID`=34773 AND `locale`='frFR');
