UPDATE `broadcast_text_locale` SET `MaleText_lang`='QU’EST-CE LÀ ? YALDA ? HAHAHAHAHA, VOUS NE POUVEZ RIEN FAIRE POUR M’ARRÊTER, VOUS OU CES AUTRES ESPRITS !', `VerifiedBuild`=25549 WHERE (`ID`=33232 AND `locale`='frFR');
