UPDATE `broadcast_text_locale` SET `MaleText_lang`='VOUS OSEZ ?! AUJOURD’HUI, VOUS ALLEZ ASSISTER À LA CHUTE DE LOR’DANEL, À CELLE DE MALFURION, ET À LA VÔTRE !', `VerifiedBuild`=25549 WHERE (`ID`=33229 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='VOUS AUTRES MORTELS ÊTES FAITS DE L’ÉTOFFE DES ÉLÉMENTS. COMMENT POUVEZ-VOUS ESPÉRER L’EMPORTER ? PRÉPAREZ-VOUS À RETROUVER VOTRE NATURE FONDAMENTALE !', `VerifiedBuild`=25549 WHERE (`ID`=33228 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il N’Y A QU’UNE ISSUE POSSIBLE. LE CATACLYSME N’ÉTAIT QU’UN COMMENCEMENT. LE MONDE TEL QUE VOUS LE CONNAISSEZ TOUCHE À SA FIN !', `VerifiedBuild`=25549 WHERE (`ID`=33227 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=33226 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='PATIENCE ! LE RITUEL QUI M’AMÈNERA EN CE MONDE EST COMPLEXE, ET NE SOUFFRE AUCUNE PRÉCIPITATION !', `VerifiedBuild`=25549 WHERE (`ID`=33225 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='MON MAÎTRE ARRIVE, MORTELS ! JE NE SUIS QUE LE PREMIER D’UNE LÉGION DE MESSAGERS. VOTRE MONDE VA CONNAÎTRE UNE TRANSFORMATION QUI SERA VOTRE PERTE !', `VerifiedBuild`=25549 WHERE (`ID`=33224 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='MALFURION, TU M’ENTENDS ? QUAND J’EN AURAI TERMINÉ AVEC LES ENFANTS D’ELUNE, JE VIENDRAI METTRE FIN À TES JOURS !', `VerifiedBuild`=25549 WHERE (`ID`=33223 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='JE VOUS VOIS, INSECTE. FUYEZ TANT QUE VOUS LE POUVEZ. FUYEZ, ET ALLEZ PRÉVENIR VOTRE PITOYABLE LOR’DANEL QUE J’ARRIVE POUR L’ANÉANTIR !', `VerifiedBuild`=25549 WHERE (`ID`=33222 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='MON ARRIVÉE EST IMMINENTE. MARTEAU DU CRÉPUSCULE, NE BÂCLEZ PAS L’INVOCATION, OU JE VOUS ÉCRASERAI AUSSI !', `VerifiedBuild`=25549 WHERE (`ID`=33221 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=33220 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez des embrouilles avec Tzu-Tzu ? Mais c’est pas grave… Aetherion, il est là, mec. Le camp de réfugiés, on va le pulvériser, puis ensuite on va tout casser à Lor’danel. Mais d’abord, vous, vous mourez !', `VerifiedBuild`=25549 WHERE (`ID`=33219 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Hé, mais caisse vous faites, mec ? Savez pas que la fin du monde, elle arrive ? J’vais vous montrer !', `VerifiedBuild`=25549 WHERE (`ID`=33218 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Si vous saviez seulement quelles puissances je sers, vous n’hésiteriez pas à vous prosterner devant moi pour rejoindre nos rangs. Malheureusement, votre ignorance sera votre perte !', `VerifiedBuild`=25549 WHERE (`ID`=33217 AND `locale`='frFR');
