UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le Vent a utilisé ses serviteurs pour déformer l’histoire de cet endroit, changer les légendes transmises par ton peuple, détruisant ainsi les esprits des morts révérés.', `VerifiedBuild`=25549 WHERE (`ID`=32752 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mais le Vent du Nord n’a pas accepté la défaite par son silence. Non, il a rassemblé son pouvoir et attendu son heure, décidant que la meilleure des vengeances était de détruire tout souvenir de toi et, avec ça, ton village.', `VerifiedBuild`=25549 WHERE (`ID`=32751 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ta bataille contre le Vent a eu lieu il y a des centaines d’années, Sabot-Tempête. Tu l’avais tant affaibli qu’il est resté silencieux toutes ces années.', `VerifiedBuild`=25549 WHERE (`ID`=32750 AND `locale`='frFR');
