UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le roi Foudrecœur a appris que les nains de fer se dirigeaient par ici et rassemblé tous les meilleurs guerriers qu’il a pu trouver en aussi peu de temps.', `VerifiedBuild`=25549 WHERE (`ID`=30988 AND `locale`='frFR');
