UPDATE `broadcast_text_locale` SET `MaleText_lang`='Voilà donc l’épreuve que nous vous envoyons aujourd’hui. Ne revenez que quand le Guetteur de fer sera mort, et vous serez $grévéré:révérée; en tant que $gguerrier:guerrière; des givre-nés.', `VerifiedBuild`=25549 WHERE (`ID`=30956 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Et dans l’une des épreuves les plus féroces affrontée par un guerrier givre-né, nous devons faire face à une créature bien plus grande que nous : géants, dragons, jormungars... C’est un témoignage du fait que la taille ne sera jamais notre faiblesse.', `VerifiedBuild`=25549 WHERE (`ID`=30955 AND `locale`='frFR');
