UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mais pourquoi est-ce qu’ils ne t’ont pas emporté toi au lieu de Dargath ? POURQUOI ?! POURQUOI, HEIN ?! POURQUOI ?!', `VerifiedBuild`=25549 WHERE (`ID`=30447 AND `locale`='frFR');
