UPDATE `broadcast_text_locale` SET `MaleText_lang`='Réfléchissez, $n. Pensez au passé. Essayez de vous rappeler les majestiques demeures de Lune-d’Argent, où vous êtes $gné:née;. Rappelez-vous la splendeur de la vie, $gmon frère:ma sœur;. Autrefois, vous étiez $gun champion:une championne; sin’dorei ! Ça, ce n’est pas vous.', `FemaleText_lang`='Réfléchissez, $n. Pensez au passé. Essayez de vous rappeler les majestiques demeures de Lune-d’Argent, où vous êtes $gné:née;. Rappelez-vous la splendeur de la vie, $gmon frère:ma sœur;. Autrefois, vous étiez $gun champion:une championne; sin’dorei ! Ça, ce n’est pas vous.', `VerifiedBuild`=25549 WHERE (`ID`=29374 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous ne vous souvenez pas de moi, hein ? Maudit Fléau… Ils ont voulu vous enlever tout ce qui faisait de vous une valeureuse force de jugement. Chaque parcelle de bien en vous, jusqu’à la dernière… Tout ce qui faisait de vous $gun:une; elfe de sang !', `FemaleText_lang`='Vous ne vous souvenez pas de moi, hein ? Maudit Fléau… Ils ont voulu vous enlever tout ce qui faisait de vous une valeureuse force de jugement. Chaque parcelle de bien en vous, jusqu’à la dernière… Tout ce qui faisait de vous $gun:une; elfe de sang !', `VerifiedBuild`=25549 WHERE (`ID`=29373 AND `locale`='frFR');
