UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je… Je n’en ai plus pour très longtemps. Je suis condamné. Achevez-moi, $n. Faites-le, ou ils nous tueront tous les deux. $n… Souvenez-vous d’Argus. Il y a tant à sauver en ce monde.', `VerifiedBuild`=25549 WHERE (`ID`=29364 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Écoutez-moi, $n. Vous devez combattre l’emprise du roi-liche. C’est un monstre qui veut la ruine de ce monde - notre monde ! Ne le laissez pas vous utiliser pour satisfaire ses desseins. Autrefois, vous étiez $gun héros:une héroïne; et vous pouvez l’être à nouveau. Battez-vous, bon sang ! Rejetez son influence !', `VerifiedBuild`=25549 WHERE (`ID`=29363 AND `locale`='frFR');
