UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’Alliance tient ce gîte isolé depuis quelque temps. Nos chasseurs et forestiers l’utilisent de temps en temps.$B$BMais maintenant que la guerre fait rage, les militaires en ont pris le contrôle, évidemment.', `VerifiedBuild`=25549 WHERE (`ID`=27107 AND `locale`='frFR');
