UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Le Vol infini tente de modifier le destin du prince Arthas Menethil.$B$BPour vous, il est le roi-liche, mais ici et maintenant il est encore un prince de Lordaeron qui essaie de faire au mieux pour défendre son royaume.$B$BAujourd’hui, Arthas va effectuer un choix lourd de conséquences, qui mènera à ce que nous autres Gardiens du temps appelons un point d’inflexion dans la voie temporelle.', `VerifiedBuild`=25549 WHERE (`ID`=27091 AND `locale`='frFR');
