UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=27046 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il faut que Thel’zan meure, ne serait-ce que pour mettre fin à ces jérémiades !', `VerifiedBuild`=25549 WHERE (`ID`=27045 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=27044 AND `locale`='frFR');
