UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je connaissais un nain qui prétendait que les gnomes venaient de sous la terre. Qu’on descend tous de gnomes des sables. Quel ramassis d’âneries ! Des gnomes des sables ? N’IMPORTE QUOI !', `FemaleText_lang`='Je connaissais un nain qui prétendait que les gnomes venaient de sous la terre. Qu’on descend tous de gnomes des sables. Quel ramassis d’âneries ! Des gnomes des sables ? N’IMPORTE QUOI !', `VerifiedBuild`=25549 WHERE (`ID`=26977 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il y a quelque chose qui refoule méchamment, ici ! Aucune chance pour que ce soit moi : les gnomes ont l’odeur de la crème et des rayons de soleil. Pas comme les nains, qui sentent comme s’ils étaient nés dans une aisselle de trogg ! Y a pas de nain parmi vous, hein ?', `FemaleText_lang`='Il y a quelque chose qui refoule méchamment, ici ! Aucune chance pour que ce soit moi : les gnomes ont l’odeur de la crème et des rayons de soleil. Pas comme les nains, qui sentent comme s’ils étaient nés dans une aisselle de trogg ! Y a pas de nain parmi vous, hein ?', `VerifiedBuild`=25549 WHERE (`ID`=26976 AND `locale`='frFR');
