UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Et merci… Merci de m’avoir libérée des chaînes des damnés. Vous êtes $gun héros:une héroïne;… et vous êtes $gpromis:promise; à de grandes choses.', `VerifiedBuild`=25549 WHERE (`ID`=26942 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Mon temps est passé… J’ai fait don de moi à Alexstrasza de mon vivant mais, morte, je n’ai plus rien à offrir. Il lui faudra un nouveau gardien pour son sanctuaire.', `VerifiedBuild`=25549 WHERE (`ID`=26941 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=26940 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='J’ai vécu ici comme gardienne de ce temple, avec la bénédiction d’Alexstrasza, aussi loin que remontent mes souvenirs. Et dans son heure la plus sombre, j’ai échoué… Je suis tombée aux pieds de ce satané chevalier de la mort... Sangreplaie.', `VerifiedBuild`=25549 WHERE (`ID`=26939 AND `locale`='frFR');
