UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Prépare-les bien, Raelorasz. Malygos détient une puissance dont ils n’ont jamais vu la pareille. Cette diversion ne pourra sans doute que retarder la mise à exécution de son plan.', `VerifiedBuild`=25549 WHERE (`ID`=25469 AND `locale`='frFR');
