UPDATE `broadcast_text_locale` SET `MaleText_lang`='La créature Entropius, que vous avez dû détruire, était autrefois le noble M’uru - un naaru qui de son vivant canalisait d’intenses énergies de LUMIÈRE et d’ESPOIR. Pendant un temps, certaines âmes égarées ont cherché à dérober ces énergies…', `VerifiedBuild`=25549 WHERE (`ID`=25407 AND `locale`='frFR');
