UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ne prenez pas un air si satisfait ! Je sais à quoi vous pensez, mais le donjon de la Tempête n’était qu’un petit contretemps. Croyez-vous vraiment que je confierais notre avenir à un aveugle, un bâtard demi-elfe de la nuit ?', `VerifiedBuild`=25549 WHERE (`ID`=25386 AND `locale`='frFR');
