UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pourquoi est-ce que vous n’abandonnez pas, tout simplement ? Pourquoi est-ce que vous vous acharnez à combattre l’inévitable ?', `VerifiedBuild`=25549 WHERE (`ID`=24914 AND `locale`='frFR');
