UPDATE `broadcast_text_locale` SET `MaleText_lang`='Non, nous n’avons malheureusement pas encore pris le port. Cependant, les rapports indiquent que nous en sommes à $3238w pour cent de l’objectif.$B$B$n, si vous voulez aider, allez trouver le magistère Ilastar et le redresseur de torts Kaalan à l’armurerie des confins du Soleil, sur l’île de Quel’Danas.', `VerifiedBuild`=25549 WHERE (`ID`=24228 AND `locale`='frFR');
