UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les guerriers seront déployés pour tenir les points clés pendant que vous, les tireurs d’élite, aurez pour mission de tenir les troupes volantes ennemies à distance.', `VerifiedBuild`=25549 WHERE (`ID`=24220 AND `locale`='frFR');
