UPDATE `broadcast_text_locale` SET `MaleText_lang`='Salut, et bienvenue à la fête des Brasseurs ! Il y a tout un tas de façons de vous amuser par ici, donc, si vous avez la moindre question, n’hésitez pas à venir me voir. Sinon, allez chercher une bière et un bretzel !', `VerifiedBuild`=25549 WHERE (`ID`=23763 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='La course de béliers est l’une des grandes traditions de la fête des Brasseurs. Allez voir Pol Distillambre près de l’étable aux béliers si vous voulez en savoir plus. C’est super marrant ET ça peut être un très bon moyen de gagner des jetons de la fête des Brasseurs !', `VerifiedBuild`=25549 WHERE (`ID`=23762 AND `locale`='frFR');
