UPDATE `broadcast_text_locale` SET `MaleText_lang`='D’après vous, quel est le problème ? Le sol est gelé, aussi dur que de la pierre !$B$BLes roues des chariots à viande ont été conçues pour rouler sur la boue, au mieux. Il va nous falloir une abomination et des chaînes pour réussir à les sortir de là.', `VerifiedBuild`=25549 WHERE (`ID`=22595 AND `locale`='frFR');
