UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oui, on a dit que tu pouvais rester, mais ce bâtiment est notre quartier général. C’est là qu’on garde tous nos manuels et tous nos plans !', `VerifiedBuild`=25549 WHERE (`ID`=22590 AND `locale`='frFR');
