UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous pourriez vous demander : « et maintenant ? » J’ai la réponse. Pour en apprendre plus sur notre art, vous devez voyager par-delà les mers, jusqu’à l’imposante cité de Forgefer. La forge qui s’y trouve est l’une des plus grande du monde ! Bengus Forge-profonde demeure dans la Grande Forge. Il pourra poursuivre votre enseignement.', `VerifiedBuild`=25549 WHERE (`ID`=22573 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=22572 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='N’avez-vous jamais rêvé de contempler les rameaux de Teldrassil, $n ? Vous devriez, car là-bas se trouve un elfe qui pourra vous en apprendre plus. Allez trouver Ainethil à Darnassus, sur la terrasse des Artisans.', `VerifiedBuild`=25549 WHERE (`ID`=22571 AND `locale`='frFR');
