UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai vu un bon paquet de choses dans ma carrière, mais le changement qui a touché la Ligue des explorateurs au goulet des Murmures remporte la palme.$B$BJe suis juste bien content d’avoir pu me sortir de là sans y laisser ma peau.', `VerifiedBuild`=25549 WHERE (`ID`=22558 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='De toute ma vie, je n’aurais jamais pensé voir s’ouvrir une nouvelle frontière aussi magnifique.$B$BSi seulement elle n’était pas souillée par le mal et par un savoir qui devrait rester caché.', `VerifiedBuild`=25549 WHERE (`ID`=22557 AND `locale`='frFR');
