UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Toutes ces bouches à nourrir, et qui doit s’en occuper ? Moi !$B$BToute la cuisine, tout le ménage, et tout le reste !', `VerifiedBuild`=25549 WHERE (`ID`=22554 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’apporte mon conseil au capitaine sur les sujets dont il choisit de me faire part, mais j’ai l’impression qu’il préfère s’adresser à vous.', `VerifiedBuild`=25549 WHERE (`ID`=22553 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous n’aurions pas dû laisser tant de gens à Valgarde. Cet amiral Keller est d’une vanité sans nom !$B$BComment puis-je accomplir ma mission avec si peu d’hommes ? Il m’en faut assez pour rester et tenir le donjon, tout en mettant une garnison suffisante au fort Hardivar dès qu’il sera prêt !$B$BAu moins nous avons une occasion de nous occuper de nos ennuis maintenant que vous êtes là.', `VerifiedBuild`=25549 WHERE (`ID`=22552 AND `locale`='frFR');
