UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez l’air de quelqu’un d’intelligent. Lisez donc un de nos pamphlets et réfléchissez-y, d’accord ?', `FemaleText_lang`='Vous avez l’air de quelqu’un d’intelligent. Lisez donc un de nos pamphlets et réfléchissez-y, d’accord ?', `VerifiedBuild`=25549 WHERE (`ID`=22549 AND `locale`='frFR');
