UPDATE `broadcast_text_locale` SET `MaleText_lang`='La foire de Sombrelune est le plus grand évènement sur toute l’Outreterre !', `FemaleText_lang`='La foire de Sombrelune est le plus grand évènement sur toute l’Outreterre !', `VerifiedBuild`=25549 WHERE (`ID`=22546 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=22545 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Bienvenue à tous au plus grand spectacle de tous les mondes... la Foire de Sombrelune ! Tout y est... l’excellente nourriture, les boissons fortes, les bibelots exotiques, la bonne aventure, des prix incroyables et des animations sans fin ! N’oubliez pas de remettre vos bons de la foire de Sombrelune à Gelvas Crasseporte ! À partir de cinq, vous êtes déjà en passe d’obtenir les prix les plus mirifiques de toute l’Outreterre ! Il n’y a que des gagnants !', `VerifiedBuild`=25549 WHERE (`ID`=22544 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous vous amusez bien ? Parfait ! Bienvenue à la foire de Sombrelune, le plus grand spectacle de toute l’Outreterre ! Pensez à parler à Yebb et à ses amis quand vous admirerez le Bazar du bizarre sombrelunien de Becquabrach.', `VerifiedBuild`=25549 WHERE (`ID`=22543 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Chers amis, soyez les bienvenus au plus grand spectacle d’Azeroth !$B$BJe vous en prie, entrez et voyez tout ce que nous avons à offrir. Profitez des attractions et admirez les phénomènes ! Contemplez les merveilles découvertes par la foire de Sombrelune à travers le vaste monde ! Nous avons dépensé sans compter pour vous apporter la féerie qui fera la joie des enfants de tous âges !', `VerifiedBuild`=25549 WHERE (`ID`=22542 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Bienvenue à tous au plus grand spectacle d’Azeroth… la foire de Sombrelune ! L’aventure et le frisson vous attendent, ne soyez pas timides ! Il y a des mystères à découvrir et des prix à gagner pour les jeunes et les moins jeunes. Et n’oubliez pas d’aller consulter le professeur à propos des cartes de Sombrelune que vous auriez pu trouver au cours de vos voyages !', `VerifiedBuild`=25549 WHERE (`ID`=22541 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Salutations, mon $gami:amie;, et bienvenue dans le plus grand spectacle de toute l’Outreterre !$B$BJe vous en prie, entrez et voyez tout ce que nous avons à offrir. Contemplez les merveilles découvertes par la foire de Sombrelune à travers le vaste monde ! Nous avons dépensé sans compter pour vous apporter la féerie qui fera la joie des enfants de tous âges !', `VerifiedBuild`=25549 WHERE (`ID`=22540 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Heureux de vous revoir au plus grand spectacle de toute l’Outreterre, mon $gami:amie; ! C’est toujours un plaisir de vous retrouver.$B$BJe vous en prie, entrez et voyez encore tout ce que nous avons à offrir. Et ouvrez l’œil, car nous ajoutons sans discontinuer de nouvelles et époustouflantes attractions à la Foire de Sombrelune ! Contemplez les merveilles antiques ou modernes que nous avons découvertes ! Nous continuons à dépenser sans compter pour vous apporter la féerie qui fera la joie des enfants de tous âges !', `VerifiedBuild`=25549 WHERE (`ID`=22539 AND `locale`='frFR');
