UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Il y a huit séries de cartes de Sombrelune : Bénédictions, Déraison, Élémentaires, Fauves, Furies, Orages, Portails et Seigneurs de guerre. Chacune d’entre elles comporte huit cartes, de l’as au huit. Si vous les réunissez toutes les huit, vous pourrez former une suite à remettre au professeur Thaddeus Paleo en échange d’un puissant bijou.', `VerifiedBuild`=25549 WHERE (`ID`=22527 AND `locale`='frFR');
