UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez commencé par devenir $groi:reine; des ogres d’en bas, puis vous avez su provoquer des sentiments exaltés parmi nous autres à Ogri’la.$B$BC’est une chose sans précédent pour $gun:une:r; $r, et pourtant vous en êtes une preuve vivante. Je vous remercie, $n, et nous avons tous envers vous une dette dont nous ne pourrons jamais entièrement nous acquitter.', `VerifiedBuild`=25549 WHERE (`ID`=21593 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='On commence à révérer votre nom dans la région.$B$B<L’œil gauche de Chu’a’lor vous lance un regard perçant.>$B$BContinuez comme ça, $n !', `VerifiedBuild`=25549 WHERE (`ID`=21592 AND `locale`='frFR');
