UPDATE `broadcast_text_locale` SET `FemaleText_lang`='J’espère que vous penserez pas que je vous harcèle, ou un truc du genre, $n.$B$BEnfin, je sais que vous êtes vraiment célèbre dans la Garde-ciel maintenant, et bon... je suis sûre que vous avez mieux à faire que de passer votre temps avec une pauvre péone comme moi.$B$BMais si jamais vous voulez qu’on se retrouve un soir, ou si vous voulez dompter encore quelques raies, c’est quand vous voulez ! Je serai là.$B$BVous me manquez...', `VerifiedBuild`=25549 WHERE (`ID`=21588 AND `locale`='frFR');
