UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oh que non. Vous n’êtes pas encore assez $gpuissant:puissante; pour participer à une rencontre officielle. Mais vous pouvez aller trouver un maître de guerre de l’arène pour participer à des matchs d’entraînement. Il n’est jamais trop tôt pour s’y mettre.', `FemaleText_lang`='Oh que non. Vous n’êtes pas encore assez $gpuissant:puissante; pour participer à une rencontre officielle. Mais vous pouvez aller trouver un maître de guerre de l’arène pour participer à des matchs d’entraînement. Il n’est jamais trop tôt pour s’y mettre.', `VerifiedBuild`=25549 WHERE (`ID`=21410 AND `locale`='frFR');
