UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez donc vaincu le Cachet cramoisi. Et vous voulez maintenant défier mon autorité ? Même Arthas n’a pas pu me terrasser, et vous osez pourtant en rêver ? Très bien, venez ! Venez, $n, le Temple noir vous attend…', `VerifiedBuild`=25549 WHERE (`ID`=19801 AND `locale`='frFR');
