UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il y a un vieux proverbe qui dit : « Donne un poisson à un homme, tu le nourriras pour un jour. Apprends-lui à pêcher, tu le nourriras pour toujours. ». Mais évidemment, vous aurez peut-être envie de le cuisiner, ce poisson. C’est là que j’interviens.', `VerifiedBuild`=25549 WHERE (`ID`=19753 AND `locale`='frFR');
