UPDATE `broadcast_text_locale` SET `MaleText_lang`='Voilà, ça, c’est ce que je veux entendre !$B$BJe suis content que nous ayons eu cette petite réunion. Je suis rassuré au sujet de l’attaque, maintenant. Avec des chefs comme toi sur la ligne de front, comment pourrions-nous perdre ?$B$BBon, tu as tes ordres de marche. Maintenant, retourne à la sylve Ruuan et mets tout en place !', `VerifiedBuild`=25549 WHERE (`ID`=19692 AND `locale`='frFR');
