UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai installé quelques consoles de contrôle plus bas. Trouvez-en une rapidement et prenez contrôle du saccageur gangrené ! Vous n’aurez qu’un temps limité pour y arriver.', `VerifiedBuild`=25549 WHERE (`ID`=19666 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Haha, vous revoilà ? Vous n’espérez quand même pas sérieusement que je vais changer d’avis, si ?$B$BBarrez-vous.', `VerifiedBuild`=25549 WHERE (`ID`=19665 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous sommes venus dans la sylve Ruuan pour tenter de rétablir l’équilibre naturel de ces montagnes.$B$BCependant, les interférences causées par les arakkoa et le culte du Ver rendent cette tâche très difficile.$B$BHeureusement, il y a aussi des gens comme Samia et vous qui acceptent de nous prêter main-forte.', `VerifiedBuild`=25549 WHERE (`ID`=19664 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Des négociations ? DES NÉGOCIATIONS ?!$B$BPermettez-moi de vous exposer très clairement notre position. Nous sommes un peuple libre, nous faisons ce que nous voulons et allons où nous voulons. L’Expédition cénarienne ne possède pas cette chaîne de montagnes.$B$BIl n’y aura aucune négociation ! Maintenant, retournez voir les druides, et dites-leur que nous continuerons à faire comme il nous plaît.', `VerifiedBuild`=25549 WHERE (`ID`=19663 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Surveillant, je suis ici pour négocier au nom de l’Expédition cénarienne.', `FemaleText_lang`='Surveillant, je suis ici pour négocier au nom de l’Expédition cénarienne.', `VerifiedBuild`=25549 WHERE (`ID`=19662 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les Tranchantes offrent de nombreuses opportunités. Il est malheureux que certaines personnes se considèrent supérieures à toutes les autres en ce qui concerne l’exploitation de ces opportunités.$B$BPour qui se prennent-ils dans l’Expédition cénarienne, pour nous dire ce que nous pouvons ou ne pouvons pas faire ?', `VerifiedBuild`=25549 WHERE (`ID`=19661 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='La dernière fois que quelqu’un s’est mis en tête de gagner la récompense promise pour Néantroche, tout ce qu’on en a retrouvé, c’est une fine couche d’aventurier téméraire compacté !', `FemaleText_lang`='La dernière fois que quelqu’un s’est mis en tête de gagner la récompense promise pour Néantroche, tout ce qu’on en a retrouvé, c’est une fine couche d’aventurier téméraire compacté !', `VerifiedBuild`=25549 WHERE (`ID`=19660 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Néantroche ? Ce truc peut vous aplatir comme une crêpe d’un seul mouvement de son gigantesque pied ! Non merci !', `FemaleText_lang`='Néantroche ? Ce truc peut vous aplatir comme une crêpe d’un seul mouvement de son gigantesque pied ! Non merci !', `VerifiedBuild`=25549 WHERE (`ID`=19659 AND `locale`='frFR');
