UPDATE `broadcast_text_locale` SET `MaleText_lang`='Zarath, je suis parfaitement capable de remonter la route jusqu’à la halte de l’Éclipse tout seul. Si nous n’assurons pas la livraison de la missive, ce sont nos peaux à nous deux qu’aura le seigneur Illidan ! Vous pouvez disposer !', `VerifiedBuild`=25549 WHERE (`ID`=19175 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Seigneur, vous ne vous attendiez sûrement pas à ce que je vous laisse sans protection. Le seigneur Illidan aurait ma peau s’il vous arrivait quoi que ce soit.', `VerifiedBuild`=25549 WHERE (`ID`=19174 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Zarath, il faut que vous retourniez au Temple noir sur-le-champ ! Il… Il semble que j’aie égaré temporairement les ordres du seigneur Illidan. Faites vite !', `VerifiedBuild`=25549 WHERE (`ID`=19173 AND `locale`='frFR');
