UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ne vous inquiétez pas. J’ai augmenté le rythme de production à la Forgemort. Vous aurez tous les infernaux qu’il vous faudra pour exécuter vos ordres. N’échouez pas, Jovaan.', `VerifiedBuild`=25549 WHERE (`ID`=19151 AND `locale`='frFR');
