UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’espère que le transporteur ultra-sécurisé ne vous fera jamais défaut ! Je sais bien que ce ne sera jamais le cas, mais je conseille le port d’une cape parachute juste au cas où !', `VerifiedBuild`=25549 WHERE (`ID`=19136 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis content de pouvoir discuter avec $gun:une; collègue dans l’ingénierie gobeline ! Il y a tant d’ingénieurs gobelins qui viennent apprendre à fabriquer le déchiqueteur dimensionnel et qui ne nous donnent plus jamais de nouvelles… C’est intrigant.', `VerifiedBuild`=25549 WHERE (`ID`=19135 AND `locale`='frFR');
