UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une fois l’appareil assemblé, il vous suffit de l’activer pour être $gtransporté:transportée; au poste de Toshley ! Quelques personnes se sont plaintes d’avoir été transformées en poulets, mais je suis sûr qu’elles exagéraient !\n\nÀ votre place, j’essayerais d’éviter d’utiliser l’appareil un jour où quelqu’un d’autre s’en est déjà servi, mais il devrait fonctionner correctement même si c’est le cas !', `VerifiedBuild`=25549 WHERE (`ID`=19133 AND `locale`='frFR');
