UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis… mort.$B$BPourquoi suis-je encore là ? Ne devais-je pas m’élever vers un grand terrain de chasse ?$B$BNon… Il faut d’abord que j’accomplisse ma mission. Avant de quitter ce monde, il faut retrouver la deuxième partie de la Formule de damnation.', `FemaleText_lang`='Je suis… morte.$B$BPourquoi suis-je encore là ? Ne devais-je pas m’élever vers un grand terrain de chasse ?$B$BNon… Il faut d’abord que j’accomplisse ma mission. Avant de quitter ce monde, il faut retrouver la deuxième partie de la Formule de damnation.', `VerifiedBuild`=25549 WHERE (`ID`=18978 AND `locale`='frFR');
