UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous ne pourrez pas acheter de faucon-pérégrin ici tant que vous n’aurez pas prouvé votre valeur et votre dévouement envers notre peuple.$B\n\nNe revenez pas avant d’être $gexalté:exaltée; par les elfes de sang.\n$b\nAllons, du balai !', `VerifiedBuild`=25549 WHERE (`ID`=18925 AND `locale`='frFR');
