UPDATE `broadcast_text_locale` SET `MaleText_lang`='Minuit est la monture personnelle d’Attumen le Veneur. Je n’ai jamais vu de jument aussi rapide, puissante ou dotée d’un tel caractère. Et son cavalier est encore plus fantasque ! Tout le monde se tient à distance respectueuse, sous peine de recevoir un coup de sabot dans la tête de la part de Minuit ou une volée d’Attumen.', `VerifiedBuild`=25549 WHERE (`ID`=18418 AND `locale`='frFR');
