UPDATE `broadcast_text_locale` SET `MaleText_lang`='Socrethar embrume ton esprit, Kaylaan ! Tu ne penses pas ce que tu dis ! Je me souviens t’avoir entraîné dans ta jeunesse. Même alors, ta volonté était farouche !', `VerifiedBuild`=25549 WHERE (`ID`=18397 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Quand j’ai pu canaliser la haine qui occupait mon cœur, tout est devenu clair à mes yeux. Shattrath doit être détruite, et les naaru avec.', `VerifiedBuild`=25549 WHERE (`ID`=18396 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’avais tourné cette haine contre les Illidari et la Légion ardente… mais ce ne sont pas eux qui nous ont trahis. Nous étions les élus des naaru ! Nous vivions et mourions pour eux !', `VerifiedBuild`=25549 WHERE (`ID`=18395 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mon cœur est empli de haine depuis que nos ennemis jurés ont été accueillis dans notre ville. Je connaissais celui que l’on appelle Voren’thal avant qu’il ne devienne un Clairvoyant. C’est par sa main que mon frère a péri.', `VerifiedBuild`=25549 WHERE (`ID`=18394 AND `locale`='frFR');
