UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oui, finissons-en. Mais avant que nous commencions, je voudrais vous présenter quelqu’un.', `VerifiedBuild`=25549 WHERE (`ID`=18392 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous sommes peut-être peu nombreux, Socrethar, mais forte est notre foi. Et cela vous ne le comprendrez jamais. Maintenant que l’usage a été respecté, préparez-vous, votre fin arrive.', `VerifiedBuild`=25549 WHERE (`ID`=18391 AND `locale`='frFR');
