UPDATE `broadcast_text_locale` SET `MaleText_lang`='Dulvi est la femme qu’il vous faut. Elle entraîne les prospecteurs débutants au centre du Guet.', `FemaleText_lang`='Dulvi est la femme qu’il vous faut. Elle entraîne les prospecteurs débutants au centre du Guet.', `VerifiedBuild`=25549 WHERE (`ID`=18335 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nos nouveaux alliés, les furbolgs Calmepins, nous ont dit être intéressés par les peaux que nous trouvons. Ils vivent au nord d’ici. À votre place, j’irais chercher des connaissances auprès d’eux.', `FemaleText_lang`='Nos nouveaux alliés, les furbolgs Calmepins, nous ont dit être intéressés par les peaux que nous trouvons. Ils vivent au nord d’ici. À votre place, j’irais chercher des connaissances auprès d’eux.', `VerifiedBuild`=25549 WHERE (`ID`=18334 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Heur étudie la flore locale depuis notre atterrissage. Il pourra vous guider. Vous le trouverez aux côtés de Daedal sur le bord ouest du Guet d’azur.', `FemaleText_lang`='Heur étudie la flore locale depuis notre atterrissage. Il pourra vous guider. Vous le trouverez aux côtés de Daedal sur le bord ouest du Guet d’azur.', `VerifiedBuild`=25549 WHERE (`ID`=18333 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='On veut devenir $gpêcheur:pêcheuse; à la ligne ? Eh bien, Diktynna vit sur la rive du gué d’Ammen, et sa canne et son filet nous ravitaillent tous. Je suis sûr qu’un peu d’aide lui serait utile.', `FemaleText_lang`='On veut devenir $gpêcheur:pêcheuse; à la ligne ? Eh bien, Diktynna vit sur la rive du gué d’Ammen, et sa canne et son filet nous ravitaillent tous. Je suis sûre qu’un peu d’aide lui serait utile.', `VerifiedBuild`=25549 WHERE (`ID`=18332 AND `locale`='frFR');
