UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’artificier du coin, Daelo, pourra vous enseigner les bases de l’ingénierie. Vous pourrez peut-être aider nos techniciens à réparer cet engin de communication en panne !', `FemaleText_lang`='L’artificier du coin, Daelo, pourra vous enseigner les bases de l’ingénierie. Vous pourrez peut-être aider nos techniciens à réparer cet engin de communication en panne !', `VerifiedBuild`=25549 WHERE (`ID`=18330 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nos enchanteurs passent leurs journées dans l’Exodar, à travailler sur tous leurs projets. Nahogg entamera votre apprentissage.', `FemaleText_lang`='Nos enchanteurs passent leurs journées dans l’Exodar, à travailler sur tous leurs projets. Nahogg entamera votre apprentissage.', `VerifiedBuild`=25549 WHERE (`ID`=18329 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous ne disposons pas d’un cuisinier, mais il y a quelque chose d’étrange… Des odeurs délicieuses sont portées par le vent du sud. Suivez votre odorat, hein ?', `FemaleText_lang`='Nous ne disposons pas d’un cuisinier, mais il y a quelque chose d’étrange… Des odeurs délicieuses sont portées par le vent du sud. Suivez votre odorat, hein ?', `VerifiedBuild`=25549 WHERE (`ID`=18328 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il n’y a pas de forge au Guet d’azur. Cependant, j’ai vu quelques apprentis forgerons arriver de cet étrange campement situé sur la côte au sud. Vous devriez peut-être y jeter un œil.', `FemaleText_lang`='Il n’y a pas de forge au Guet d’azur. Cependant, j’ai vu quelques apprentis forgerons arriver de cet étrange campement situé sur la côte au sud. Vous devriez peut-être y jeter un œil.', `VerifiedBuild`=25549 WHERE (`ID`=18327 AND `locale`='frFR');
