UPDATE `broadcast_text_locale` SET `MaleText_lang`='Que savez-vous des éthériens, créature de chair ?$B$BVous devez sans aucun doute nous voir tous sous le même jour et tout ignorer des luttes et conflits entre les diverses factions.$B$BPeut-être est-il temps que je me présente. Je suis le commandant Ameer, du Protectorat, et je suis également votre seul espoir de remédier à l’invasion des créatures du Vide et de l’Ethereum dans cette région.', `VerifiedBuild`=25549 WHERE (`ID`=18178 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=18177 AND `locale`='frFR');
