UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je cherche quelqu’un pour m’aider avec un problème qui aurait dû être résolu depuis longtemps.$B$BVous semblez fiable…', `VerifiedBuild`=25549 WHERE (`ID`=18174 AND `locale`='frFR');
