UPDATE `broadcast_text_locale` SET `MaleText_lang`='Plus bas ! Je ne veux pas qu’ils me voient ici.$B$BAh, ça m’exaspère vraiment ! Pour qui ces éthériens se prennent-ils ?$B$BC’est MON coin !', `VerifiedBuild`=25549 WHERE (`ID`=17296 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='La nuit où Kael’thas a rasé le village, je n’ai rien pu faire pour l’en empêcher. Sa magie me tenait déjà enfermé dans la tour, attisant mon tourment en m’obligeant à assister à la mort des miens.$B$BEt leurs voix m’appellent encore, au loin, et viennent me réveiller la nuit.', `VerifiedBuild`=25549 WHERE (`ID`=17295 AND `locale`='frFR');
