UPDATE `broadcast_text_locale` SET `MaleText_lang`='Quand la Légion ardente retourna la Horde contre les draeneï, la bataille la plus terrible eut lieu ici. Les draeneï combattirent jusqu’au dernier, mais la ville finit par tomber.', `VerifiedBuild`=25549 WHERE (`ID`=17268 AND `locale`='frFR');
