UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les attaques contre Shattrath continuèrent, mais la ville ne tomba pas, comme vous pouvez le voir. Bien au contraire, le naaru appelé Xi’ri mena avec succès une incursion dans la vallée d’Ombrelune, l’entrée du domaine d’Illidan.', `VerifiedBuild`=25549 WHERE (`ID`=17257 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Qu’est-ce que c’est que ça ? Vous n’aviez pas dit que la zone était sûre ? C’est déjà la troisième attaque ! Si nous nous en sortons, comptez sur moi pour le déduire de votre récompense. Allons, ne restez pas les bras ballants, détruisez-les pour que je puisse arriver au collecteur.', `VerifiedBuild`=25549 WHERE (`ID`=17256 AND `locale`='frFR');
