UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les marchés du secteur Xarodi sont à nouveau ouverts, maître. Les cours des saphirs de toutes sortes montent. L’argent baisse. L’or monte. Les diamants restent stables.$B$BOh, et votre frère demande que vous lui rendiez les holocubes empruntés la semaine dernière.', `VerifiedBuild`=25549 WHERE (`ID`=17188 AND `locale`='frFR');
