UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les exportations d’Heraazi sont en augmentation, maître. Nous avons d’ores et déjà soudoyé les officiers taxateurs, et les marchandises de contrebande commenceront à arriver dans quelques jours.', `VerifiedBuild`=25549 WHERE (`ID`=17186 AND `locale`='frFR');
