UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mmm… Les défenses contre le Givre, le Feu et les Arcanes ont un meilleur temps de réponse qu’avec la version 7, mais celles contre la Nature restent passives.', `FemaleText_lang`='Mmm… Les défenses contre le Givre, le Feu et les Arcanes ont un meilleur temps de réponse qu’avec la version 7, mais celles contre la Nature restent passives.', `VerifiedBuild`=25549 WHERE (`ID`=17178 AND `locale`='frFR');
