UPDATE `broadcast_text_locale` SET `MaleText_lang`='Garrosh, fils de Hurlenfer, ton père fut notre plus grand héros, de son vivant et par sa mort. Accorde-moi l’honneur de te montrer le sacrifice qu’il consentit afin que nous puissions vivre libérés de l’étreinte des démons.', `VerifiedBuild`=25549 WHERE (`ID`=17134 AND `locale`='frFR');
