UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il est mort en héros. Notre plus grand héros. C’est Grom qui nous donna la liberté à tous… J’étais à ses côtés quand il terrassa Mannoroth et mit fin à la malédiction pour toujours.', `VerifiedBuild`=25549 WHERE (`ID`=17128 AND `locale`='frFR');
