UPDATE `broadcast_text_locale` SET `MaleText_lang`='Chef-de-fusée Karlingue, commandant de la B.O.U.M, la Brigade des Opérations Ultra-orbitales Mécanisées. À votre service.$B$BTous les systèmes sont OK ? On dirait bien qu’il reste beaucoup de travail sur la fusée-de-néant X-52 !$B$BAllez les amis… On est à l’instant T moins JAMAIS, là !', `VerifiedBuild`=25549 WHERE (`ID`=16957 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Incroyable ! Je crois que je viens de découvrir que l’univers ne tourne pas autour de l’Outreterre. Non, c’est impossible !', `VerifiedBuild`=25549 WHERE (`ID`=16956 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Si j’étais intelligent, je vendrais tout ça pour acheter une place sur la fusée. J’ai le pressentiment que nous allons bientôt avoir besoin de déguerpir !', `VerifiedBuild`=25549 WHERE (`ID`=16955 AND `locale`='frFR');
