UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je ne sais pas ce qui m’a pris de sortir sans mon épée. Je l’aurais emportée si je l’avais vue ici…', `VerifiedBuild`=25549 WHERE (`ID`=16931 AND `locale`='frFR');
