UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il y a fort longtemps, dans une dimension du cosmos qui se trouve au-delà de la compréhension des mortels, est né - pour autant qu’on puisse employer ce terme - un être d’une telle puissance que son accès à l’existence a fracassé la réalité autour de lui.$B$BConnu sous le nom de Marmon, il était l’essence du son, et l’entendre parler était connaître la mort éternelle !', `VerifiedBuild`=25549 WHERE (`ID`=16915 AND `locale`='frFR');
