UPDATE `broadcast_text_locale` SET `MaleText_lang`='Z’avez l’air fatigué, $c. J’dois avoir quequ’chose pour vous. Ces amulettes, elles peuvent vous aider à sauter par-d’sus les obstacles et à nager dans les rivières comme si vous y étiez $gné:née;. Elles énergétisent la nourriture que vous mangez, pour que vos blessures se referment à vue d’œil !', `VerifiedBuild`=25549 WHERE (`ID`=16324 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='V’nez là, $r. Vous voulez quand même pas risquer vot’ vie dans un donjon, sérieusement ? Faire un boulot dégueulasse, et pour quoi ? Une babiole sans valeur ? Pfff, c’qu’il vous faut vraiment, c’est une de mes amulettes. Leur fonctionnement est garanti !', `VerifiedBuild`=25549 WHERE (`ID`=16323 AND `locale`='frFR');
