UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’coin est dangereux, pas vrai ? Savez c’qu’il vous faut ? Une protection. J’peux vous aider à défier la mort en personne ! Portez cette follepierre autour d’votre cou, voyez, et vous pourrez revenir si vous vous faites expédier dans le monde des esprits ! Une petite balade jusqu’à vot’ cadavre, et vous revoilà, $gfrais et dispos:fraîche et dispose; !', `VerifiedBuild`=25549 WHERE (`ID`=16321 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Z’avez l’air d’vous languir. L’être cher qui vous délaisse, c’est ça ? Pas d’soucis, pas d’soucis. Vous m’prenez ce médaillon, vous l’portez quand vous l’revoyez, et vous aurez plus une minute à vous, $gmon grand:ma poulette; !', `VerifiedBuild`=25549 WHERE (`ID`=16320 AND `locale`='frFR');
