UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pour qui vous prenez-vous donc, pour entrer ici comme ça et m’adresser la parole ? Je suis le chef du Conseil des ombres dans ce village. Hors de ma vue !$B$BSi jamais je vous revois, je serai la dernière personne que vous verrez jamais. Compris ?$B$BPeut-être que vous aimeriez être $genterré:enterrée; dans le labyrinthe d’Auchindoun, ou sacrifié à Marmon ?', `VerifiedBuild`=25549 WHERE (`ID`=15803 AND `locale`='frFR');
