UPDATE `broadcast_text_locale` SET `MaleText_lang`='Lorsque nous détiendrons le totem de Kar’dash, nous raserons vos villes, et nous les rebâtirons à notre usage.', `FemaleText_lang`='Lorsque nous détiendrons le totem de Kar’dash, nous raserons vos villes, et nous les rebâtirons à notre usage.', `VerifiedBuild`=25549 WHERE (`ID`=14978 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Lorsque tu seras mort sous la torture, nous irons enlever quelqu’un d’autre. L’un de vous finira par craquer et par nous donner l’information dont nous avons besoin.', `VerifiedBuild`=25549 WHERE (`ID`=14977 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le chasseur des ombres Denjai m’a envoyé ici avec un petit contingent d’ouvriers et de guerriers pour établir cet avant-poste. Nous avons à peine terminé la construction et il nous demande déjà des rapports !$B$BSi vous avez besoin de marchandises, je peux vous en proposer un petit nombre, mais nous attendons toujours la première cargaison de ravitaillement.', `VerifiedBuild`=25549 WHERE (`ID`=14976 AND `locale`='frFR');
