UPDATE `broadcast_text_locale` SET `MaleText_lang`='Narain Divinambolesque, à votre service ! Ingénieur à la retraite et maître devin ! Je peux vous prédire votre avenir avant même qu’il ne se produise !$B$BSi vous êtes là pour réapprendre une compétence d’artisanat, voyez le livre qui est posé là-bas...$B$B<Narain indique « La Divination pour les nuls ».>', `VerifiedBuild`=25549 WHERE (`ID`=11066 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ne me dites rien ! Chut ! Vous êtes ici au sujet de Porte-Cendres ?!? Oui... Oui... Non ! Au temps pour moi.$B$BQue puis-je faire pour vous aider, $r ?$B$BSi vous êtes là pour réapprendre une compétence d’artisanat, voyez le livre qui est posé là-bas...$B$B<Narain indique « La Divination pour les nuls ».>', `VerifiedBuild`=25549 WHERE (`ID`=11065 AND `locale`='frFR');
