UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=11063 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il y a un millier d’années, lorsque la Guerre des sables changeants s’est achevée, trois des nôtres se sont sacrifiés pour piéger les Qiraji dans ces salles pendant qu’Anachronos et Forteramure scellaient Ahn’Qiraj.$B$BChacun de nous fit le vœu de rechercher Merithra, Arygos et Caelestrasz si le Mur du scarabée devait un jour s’ouvrir.$B$BIl s’est ouvert... et nous sommes venus.', `VerifiedBuild`=25549 WHERE (`ID`=11062 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=11061 AND `locale`='frFR');
