UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je croirais presque que vous vous moquez de moi, $gmortel:mortelle;. Mais oui, c’est à peu près ça. Vous pouvez le faire $ghabillé:habillée;.', `VerifiedBuild`=25549 WHERE (`ID`=11056 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le général Rajaxx n’est plus ! C’est une nouvelle victoire pour Andorov.', `VerifiedBuild`=25549 WHERE (`ID`=11055 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='D’accord, permettez-moi de récapituler. Vous avez mis l’éclat de sceptre confié à votre Vol par Anachronos sur un vairon de votre propre création et maintenant vous voulez que je construise une... une bouée en arcanite ou quelque chose comme ça... pour forcer votre vairon à sortir de sa cachette ? Et je risquerais aussi de subir la colère d’un seigneur élémentaire ? Est-ce que j’ai oublié quelque chose ? Peut-être que je dois le faire nu, pendant une éclipse solaire, lors d’une année bissextile ?', `FemaleText_lang`='D’accord, permettez-moi de récapituler. Vous avez mis l’éclat de sceptre confié à votre Vol par Anachronos sur un vairon de votre propre création et maintenant vous voulez que je construise une... une bouée en arcanite ou quelque chose comme ça... pour forcer votre vairon à sortir de sa cachette ? Et je risquerais aussi de subir la colère d’un seigneur élémentaire ? Est-ce que j’ai oublié quelque chose ? Peut-être que je dois le faire nue, pendant une éclipse solaire, lors d’une année bissextile ?', `VerifiedBuild`=25549 WHERE (`ID`=11054 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='D’accord… Vous devez construire une bouée en arcanite et la placer dans l’océan. Mon vairon sera attiré par les émanations magiques. Quand il sera près de la bouée, BLAM ! Elle explosera en libérant une fabuleuse quantité d’énergie arcanique, ce qui révélera la forme véritable du vairon. Il est également possible que vous subissiez la colère de Neptulon. J’estime les chances à 50-50.', `VerifiedBuild`=25549 WHERE (`ID`=11053 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=11052 AND `locale`='frFR');
