UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez donné ce fragment à un vairon et lâché ce vairon quelque part dans la mer entre les royaumes de l’Est et ici ? Et ce vairon a des pouvoirs spéciaux ?', `FemaleText_lang`='Vous avez donné ce fragment à un vairon et lâché ce vairon quelque part dans la mer entre les royaumes de l’Est et ici ? Et ce vairon a des pouvoirs spéciaux ?', `VerifiedBuild`=25549 WHERE (`ID`=11046 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis un génie, je sais… On ne le trouvera jamais. Mais au cas où on le trouverait, j’ai donné des pouvoirs spéciaux au vairon.', `VerifiedBuild`=25549 WHERE (`ID`=11045 AND `locale`='frFR');
