UPDATE `broadcast_text_locale` SET `MaleText_lang`='La paix n’est qu’un rêve éphémère ! Que le CAUCHEMAR règne !', `VerifiedBuild`=25549 WHERE (`ID`=10886 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’espoir est une MALADIE de l’âme ! Ces terres vont flétrir et mourir !', `VerifiedBuild`=25549 WHERE (`ID`=10885 AND `locale`='frFR');
