UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je sens l’OMBRE dans vos cœurs. Il ne peut y avoir de repos pour les vilains !', `VerifiedBuild`=25549 WHERE (`ID`=10883 AND `locale`='frFR');
