UPDATE `broadcast_text_locale` SET `MaleText_lang`='Remulos, je suis rappelé... Tyrande... Dites-lui que je l’aime... Dites-lui que je vais bien… que je reviendrai... Adieu...', `VerifiedBuild`=25549 WHERE (`ID`=10878 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10877 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Cénarius combat à mes côtés. Illidan est assis sur son trône d’Outreterre, ruminant ses pensées. Je crains que sa défaite face à Arthas n’ait été plus qu’il ne pouvait supporter. La folie s’est emparée de lui, Remulos. Il rejoue ces évènements dans son esprit un millier de fois chaque jour, sauf que dans son esprit, il triomphe et Arthas est vaincu à jamais. Il est parti trop loin, mon vieil ami. Je crains que vienne rapidement le moment où notre lien sera mis à l’épreuve, et cela ne se passera pas comme au Puits de Zin-Azshari.', `VerifiedBuild`=25549 WHERE (`ID`=10876 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous êtes travailleur du cuir, n’est-ce pas ? Cette légère odeur de peaux traitées, je la reconnaîtrais n’importe où.$B$BMon père parlait d’un célèbre artisan qui vivait au village de Sudevent il y a des siècles de cela. Quel dommage que cet endroit soit maintenant en ruine.', `VerifiedBuild`=25549 WHERE (`ID`=10875 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous êtes parti trop longtemps, Malfurion. La paix entre les enfants d’Azeroth est au mieux précaire. Qu’en est-il de mon père ? De votre frère ? Avez-vous des nouvelles ?', `VerifiedBuild`=25549 WHERE (`ID`=10874 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10873 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10872 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je crains le pire, mon vieil ami. À l’intérieur du Rêve, nous affrontons un nouvel ennemi, né d’un mal ancien. La noble progéniture d’Ysera est devenue la victime des murmures anciens. On dirait que le Cauchemar a pénétré dans le royaume et cherche un nouvel hôte dans Azeroth.', `VerifiedBuild`=25549 WHERE (`ID`=10871 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il était voilé de cauchemars, Malfurion. Que se passe-t-il dans le rêve ? Qu’est-ce qui pourrait causer de telles atrocités ?', `VerifiedBuild`=25549 WHERE (`ID`=10870 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Remulos, mon vieil ami. Quelle joie de vous revoir. Je savais que le message vous parviendrait, d’une façon ou d’une autre.', `VerifiedBuild`=25549 WHERE (`ID`=10869 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10868 AND `locale`='frFR');
