UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une voix tonitruante surgit de la pierre...$B$BQu’est-ce donc ? Je perçois la présence d’un petit sectateur qui ose s’aventurer ici ! Déguerpis, vermine, si tu ne veux pas affronter le courroux des seigneurs du Conseil !', `FemaleText_lang`='Une voix tonitruante surgit de la pierre...$B$BQu’est-ce donc ? Je perçois la présence d’un petit sectateur qui ose s’aventurer ici ! Déguerpis, vermine, si tu ne veux pas affronter le courroux des seigneurs du Conseil !', `VerifiedBuild`=25549 WHERE (`ID`=10750 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une voix tonitruante surgit de la pierre...$B$BJe perçois la présence de votre médaillon de statut, sectateur... Mais vous ne portez pas d’anneau d’autorité ! Êtes-vous vraiment l’un des dirigeants du Marteau du crépuscule, ou vous contentez-vous simplement de porter les messages de vos supérieurs ?', `FemaleText_lang`='Une voix tonitruante surgit de la pierre...$B$BJe perçois la présence de votre médaillon de statut, sectateur... Mais vous ne portez pas d’anneau d’autorité ! Êtes-vous vraiment l’un des dirigeants du Marteau du crépuscule, ou vous contentez-vous simplement de porter les messages de vos supérieurs ?', `VerifiedBuild`=25549 WHERE (`ID`=10749 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10748 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une voix claire sort de la pierre...$B$BVous êtes $gvenu:venue; à nous en arborant votre titre, donc nous vous écouterons. Mais n’abusez pas de notre patience, $c. Le conseil n’a pas de temps à perdre à entendre les commérages d’un être tel que vous.', `FemaleText_lang`='Vous êtes $gvenu:venue; à nous en arborant votre titre, donc nous vous écouterons. Mais n’abusez pas de notre patience, $c. Le conseil n’a pas de temps à perdre à entendre les commérages d’un être tel que vous.', `VerifiedBuild`=25549 WHERE (`ID`=10747 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Une voix claire s’élève de la pierre…$B$BOù est votre médaillon de statut, $gpetit:petite; ? Vous ne pouvez pas parler à un duc sans prouver votre titre…', `VerifiedBuild`=25549 WHERE (`ID`=10746 AND `locale`='frFR');
