UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis Samuel Hawke, le principal fournisseur de la Ligue d’Arathor ici au bassin Arathi. Lorsque vous améliorerez votre statut auprès de nous, je vous donnerai l’accès à un superbe choix de matériel que vous pourriez trouver utile. Si vous avez besoin de réparations, je peux aussi fournir ce type de service.', `VerifiedBuild`=25549 WHERE (`ID`=10626 AND `locale`='frFR');
