UPDATE `broadcast_text_locale` SET `MaleText_lang`='Quelqu’un m’a dit un jour que ce n’est pas à un vieux singe que l’on va apprendre de nouvelles grimaces. Heureusement pour vous, j’ai découvert que c’était faux.$b$bBon. Voulez-vous que votre familier oublie ce qu’il sait ?', `FemaleText_lang`='Quelqu’un m’a dit un jour que ce n’est pas à un vieux singe que l’on va apprendre de nouvelles grimaces. Heureusement pour vous, j’ai découvert que c’était faux.$b$bBon. Voulez-vous que votre familier oublie ce qu’il sait ?', `VerifiedBuild`=25549 WHERE (`ID`=10622 AND `locale`='frFR');
