UPDATE `broadcast_text_locale` SET `MaleText_lang`='Très bien, $c ! Notre maître de guerre, Thelman Poing-d’ardoise, se trouve dans la salle de guerre, dans le donjon de Hurlevent. Il vous aidera à vous rendre dans la vallée d’Alterac.', `FemaleText_lang`='Très bien, $c ! Notre maître de guerre, Thelman Poing-d’ardoise, se trouve dans la salle de guerre, dans le donjon de Hurlevent. Il vous aidera à vous rendre dans la vallée d’Alterac.', `VerifiedBuild`=25549 WHERE (`ID`=10573 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez pris la bonne décision, $c. Vous trouverez notre maître de guerre, Glordrum Barbe-d’acier, dans la Salle d’armes. Bonne chance, $n !', `FemaleText_lang`='Vous avez pris la bonne décision, $c. Vous trouverez notre maître de guerre, Glordrum Barbe-d’acier, dans la Salle d’armes. Bonne chance, $n !', `VerifiedBuild`=25549 WHERE (`ID`=10572 AND `locale`='frFR');
