UPDATE `broadcast_text_locale` SET `MaleText_lang`='*Bzzz* *CLANK*\n\nJ’ai reçu l’ordre d’accepter des poissons rares de grande qualité et de remettre en échange de précieux accessoires de pêche de Nat Pagle. Poisson requis.\n\n*Bomp* *Buzz*', `VerifiedBuild`=25549 WHERE (`ID`=10493 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10492 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pour attraper Gahz’ranka, il vous faudra un appât spécial au puant de vase. Je les fais moi-même !$B$BMais l’appât ne suffit pas, vous aurez aussi besoin de puants de vase… Vous devez les placer dans l’appât de manière à ce qu’il pue horriblement ! Lorsque vous aurez les puants de vase, jetez l’appât au large de la pointe de Pagle à Zul’Gurub… Vous n’avez plus qu’à vous servir à boire et à attendre… mais pas longtemps, parce que Gahz’ranka ne tardera pas, c’est sûr !', `VerifiedBuild`=25549 WHERE (`ID`=10491 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je veux attraper Gahz’ranka ! Expliquez-moi comment faire !', `FemaleText_lang`='Je veux attraper Gahz’ranka ! Expliquez-moi comment faire !', `VerifiedBuild`=25549 WHERE (`ID`=10490 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Merci encore de m’avoir rapporté mon mètre ruban porte-bonheur, $n. Je vous assure qu’il m’aide à attraper de plus gros poissons !', `VerifiedBuild`=25549 WHERE (`ID`=10489 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Si vous voulez mon avis, ce qu’il y a de mieux dans la pêche, c’est la lenteur. Ça laisse le temps de réfléchir, de penser aux évènements passés et de préparer l’avenir.$B$BOh, et c’est aussi une très bonne excuse pour boire. Beaucoup.', `VerifiedBuild`=25549 WHERE (`ID`=10488 AND `locale`='frFR');
