UPDATE `broadcast_text_locale` SET `MaleText_lang`='Bienvenue au concours de pêche de la Baie-du-Butin, qui nous permet de récompenser toutes les semaines les pêcheurs les plus doués !\n\nDès que le concours de pêche débutera, vous pourrez pêcher des courbines dans n’importe quel banc de poissons de Strangleronce.', `VerifiedBuild`=25549 WHERE (`ID`=10475 AND `locale`='frFR');
