UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le premier est un bijou primordial qui doit être pris sur les puissants lieutenants hakkari : Jin’do et le seigneur sanglant.$B$BLe second est une poupée vaudou percée. On peut en trouver dans les piles d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.$B$BRamenez-les-moi tous les deux, et je vous façonnerai un enchantement puissant !', `VerifiedBuild`=25549 WHERE (`ID`=10470 AND `locale`='frFR');
