UPDATE `broadcast_text_locale` SET `MaleText_lang`='Si vous trouviez quelque moyen que ce soit d’améliorer cet appareil, faites-m’en part !', `VerifiedBuild`=25549 WHERE (`ID`=9999 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une fois que vous avez construit l’appareil, il suffit de l’activer pour être projeté dans la merveilleuse Gadgetzan ! Presque tous ceux qui l’ont utilisé sont arrivés sur cette plateforme avec la même apparence que lorsqu’ils étaient partis !\n\nOn nous a signalé quelques problèmes de voyageurs remplacés par leur double maléfique venu d’un univers parallèle, mais je suis sûr que nous aurons bientôt corrigé ça...', `VerifiedBuild`=25549 WHERE (`ID`=9998 AND `locale`='frFR');
