UPDATE `broadcast_text_locale` SET `MaleText_lang`='Intrus ! Envahisseurs ! L’Œil qui voit tout a été dérobé ! Il est entre les mains de $gce misérable chien:cette misérable chienne;, $n !', `VerifiedBuild`=25549 WHERE (`ID`=9034 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Je suis si contente de vous revoir, $n.$B$BL’esprit de mon frère a été libéré de la corruption, mais j’ai choisi de le pleurer ici.$B$BMerci de votre aide, $n.', `VerifiedBuild`=25549 WHERE (`ID`=9033 AND `locale`='frFR');
