UPDATE `broadcast_text_locale` SET `MaleText_lang`='Quel plaisir de vous revoir, docteur $n. J’ai suivi vos progrès et je dois dire que vous êtes désormais en mesure d’apprendre des techniques de bandage plus avancées.$B$BRevenez me voir de temps en temps, au fur et à mesure que vos compétences s’étofferont, je vous apprendrai tout ce que je sais.', `VerifiedBuild`=25549 WHERE (`ID`=8970 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Salutations, $n. Je suis le docteur Gregory Victor, chirurgien-chef de l’unité médicale de la Horde.', `VerifiedBuild`=25549 WHERE (`ID`=8969 AND `locale`='frFR');
