UPDATE `broadcast_text_locale` SET `MaleText_lang`='S’il vous plaît, montrez-moi la Pierre de Maraudon.', `FemaleText_lang`='S’il vous plaît, montrez-moi la Pierre de Maraudon.', `VerifiedBuild`=25549 WHERE (`ID`=8931 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mon sceptre... Après toutes ces années... Vous l’avez retrouvé ! Vous serez véritablement le sauveur de ces lieux !$B$BÉcoutez-moi attentivement, $n. La tête et le bâton du sceptre ne peuvent être réunis qu’à la Pierre de Maraudon.', `VerifiedBuild`=25549 WHERE (`ID`=8930 AND `locale`='frFR');
