UPDATE `broadcast_text_locale` SET `MaleText_lang`='Comment cela est-il possible, $n ? Vous croyez que le Sceptre de Celebras est un objet banal ?$B$BJe peux vous aider cette fois, mais faites attention, c’est un objet précieux...', `VerifiedBuild`=25549 WHERE (`ID`=8927 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Merci de ce que vous avez fait, $n.$B$BGardez le sceptre en sûreté, et qu’il vous aide dans votre combat contre les maléfices qui ont envahi ces lieux...', `VerifiedBuild`=25549 WHERE (`ID`=8926 AND `locale`='frFR');
