UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Mes sœurs et moi sommes venues des Serres-Rocheuses pour mettre fin à une très ancienne tragédie. Malheureusement, nous n’avons pas la puissance requise pour accomplir nos objectifs par nous-mêmes et nous cherchons des mortels tels que vous pour nous aider.$B$BSi vous disposez de la puissance voulue, $c, nous devons discuter. Dans le cas contraire, pour votre sécurité, je ne mentionnerai pas les détails de notre mission.', `VerifiedBuild`=25549 WHERE (`ID`=8919 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Que Cénarius vous guide, $c.$B$BJe suis ici avec mes sœurs, dans ces terres corrompues, chargé d’une mission de grande importance pour le Cercle cénarien. Mais je dois parler de ces choses seulement à ceux qui sont assez puissants. Envoyer un être inférieur serait pure folie.', `VerifiedBuild`=25549 WHERE (`ID`=8918 AND `locale`='frFR');
