UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il semble que l’influence des dragons noirs ait dépassé les frontières des steppes Ardentes pour pénétrer dans Hurlevent ! Depuis, l’usurpateur a été démasqué et chassé.', `VerifiedBuild`=25549 WHERE (`ID`=8311 AND `locale`='frFR');
