UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis un homme simple qui connaît deux ou trois choses sur la coupe des vêtements, mais vous avez besoin de plus de conseils que je ne peux en fournir. J’ai entendu parler d’un elfe de la nuit susceptible de vous aider. Il se trouve à Hurlevent, dans le quartier des Mages.', `VerifiedBuild`=25549 WHERE (`ID`=8060 AND `locale`='frFR');
