UPDATE `broadcast_text_locale` SET `FemaleText_lang`='En tant que membres de la Horde, nous devons travailler à la pérennité de notre communauté. Je n’ai donc pas de doute : vous nous aiderez en accomplissant pour moi une petite tâche.', `VerifiedBuild`=25549 WHERE (`ID`=8048 AND `locale`='frFR');
