UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous voulez approfondir vos connaissances ? Avec moi ? Fantastique ! La seule chose que je préfère à la fabrication de munitions et d’explosifs, c’est partager mon savoir avec d’autres. Commençons !', `VerifiedBuild`=25549 WHERE (`ID`=7807 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Oh, vous avez encore bien des choses à apprendre ! Je vous enseignerais bien ce que je sais mais je suis moi-même toujours en formation. Pourquoi n’allez-vous pas parler à Trixie Quickswitch à Forgefer, elle vous aidera à parfaire votre éducation !', `VerifiedBuild`=25549 WHERE (`ID`=7806 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Salut ! Je m’appelle Jenna ! Et vous ?', `VerifiedBuild`=25549 WHERE (`ID`=7805 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='J’aimerais vous former ! Je veux montrer à ma sœur qu’elle n’est pas la seule à avoir des talents d’ingénieur…', `VerifiedBuild`=25549 WHERE (`ID`=7804 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Ma foi, ça me chagrine de l’avouer, mais c’est à ma sœur que vous devez parler si vous voulez poursuivre votre formation. J’en sais moins qu’elle... pour le moment ! Elle se trouve près du véhicule à fusées.', `VerifiedBuild`=25549 WHERE (`ID`=7803 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Il paraît que le nouveau Henweigh 6000 sera sur les chaînes de montage très bientôt. J’arrive à peine à contenir mon excitation !', `VerifiedBuild`=25549 WHERE (`ID`=7802 AND `locale`='frFR');
