UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Merci ! Merci, $gprêtre:prêtresse;. Maintenant je vais pouvoir m’occuper de ces sylvains corrompus avec l’aide des pouvoirs d’Élune.', `VerifiedBuild`=25549 WHERE (`ID`=7780 AND `locale`='frFR');
