UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Les druides disent que ce n’est qu’une question de temps avant que la nature elle-même ne chasse la Horde de Kalimdor. Pourtant la corruption continue de se propager sur nos terres, même ici sur Teldrassil.', `VerifiedBuild`=25549 WHERE (`ID`=7686 AND `locale`='frFR');
