UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Coincée dans cette petite maison, je rêve de participer aux combats qui font rage à l’extérieur de la ville. Mais j’ai pour devoir de partager mes connaissances avec ceux qui combattent pour notre camp. Du moins, pour l’instant.', `VerifiedBuild`=25549 WHERE (`ID`=7679 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous savez déjà tout ce que je suis susceptible de vous apprendre, $n. Parlez à Lilyssia Noctebrise, l’elfe de la nuit, dans le quartier des Mages de Hurlevent, si vous voulez continuer vos études. Il paraît que c’est un bon professeur.', `VerifiedBuild`=25549 WHERE (`ID`=7678 AND `locale`='frFR');
