UPDATE `broadcast_text_locale` SET `MaleText_lang`='Salut $n ! Êtes-vous là pour acheter quelque chose ? Pour vendre quelque chose peut-être ?$B$BVous ne trouverez pas de meilleurs prix ailleurs, ou alors mon nom n’est pas Augustus !', `VerifiedBuild`=25549 WHERE (`ID`=7621 AND `locale`='frFR');
