UPDATE `broadcast_text_locale` SET `MaleText_lang`='Parce que vous m’avez aidé, je vais vous dire ce que je sais de ce pays. Mes connaissances ne sont pas très vastes, mais il y a certaines choses qui peuvent intéresser quelqu’un comme vous.', `VerifiedBuild`=25549 WHERE (`ID`=7602 AND `locale`='frFR');
