UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Sachez que, où que vous les rencontriez dans ce monde, ils y sont pour protéger quelque chose d’important, car telle est la mission qui leur a été confiée il y a longtemps.', `VerifiedBuild`=25549 WHERE (`ID`=7428 AND `locale`='frFR');
