UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ta mort n’aura pas été vaine, Taelan. Un nouvel Ordre est né aujourd’hui... Un Ordre qui se consacrera à la destruction du mal qui ravage ce monde. Un mal qui ne peut se camoufler derrière la politique et les mondanités.', `VerifiedBuild`=25549 WHERE (`ID`=7426 AND `locale`='frFR');
