UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Personne ne manie aussi bien les armes qu’Ansekhwa. On dit qu’il est guidé par les esprits des meilleurs guerriers de nos ancêtres. Allez le voir sur la Cime inférieure et il vous enseignera ce que vous voulez savoir.', `VerifiedBuild`=25549 WHERE (`ID`=7255 AND `locale`='frFR');
