UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=7253 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Cherchez Sayoc et Hanashi dans la vallée de l’Honneur, à l’intérieur des "Armes de légende". Tenez votre langue, car si vous lui parlez mal, Sayoc pourrait demander à Rictus de vous grignoter un peu.', `FemaleText_lang`='Cherchez Sayoc et Hanashi dans la vallée de l’Honneur, à l’intérieur des "Armes de légende". Tenez votre langue, car si vous lui parlez mal, Sayoc pourrait demander à Rictus de vous grignoter un peu.', `VerifiedBuild`=25549 WHERE (`ID`=7252 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous voulez apprendre à utiliser une nouvelle arme ? Trouvez Sayoc et Hanashi aux "Armes de légende". C’est dans la vallée de l’Honneur.', `FemaleText_lang`='Vous voulez apprendre à utiliser une nouvelle arme ? Trouvez Sayoc et Hanashi aux "Armes de légende". C’est dans la vallée de l’Honneur.', `VerifiedBuild`=25549 WHERE (`ID`=7251 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous voulez apprendre à utiliser de nouvelles armes, pas vrai ? Ma foi, vous devriez parler à Bixi ou Buliwyf, aux Armes de Timberline. Ils savent tout utiliser, des arbalètes aux... aux zweihanders !', `FemaleText_lang`='Vous voulez apprendre à utiliser de nouvelles armes, pas vrai ? Ma foi, vous devriez parler à Bixi ou Buliwyf, aux Armes de Timberline. Ils savent tout utiliser, des arbalètes aux... aux zweihanders !', `VerifiedBuild`=25549 WHERE (`ID`=7249 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=7248 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Maître d’armes', `FemaleText_lang`='Maître d’armes', `VerifiedBuild`=25549 WHERE (`ID`=7247 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ma formation aux armes, je la dois principalement à l’entraînement d’Ilyenia Lunéclat, à la Terrasse des guerriers. Vous devriez aller la voir si vous désirez apprendre à vous servir d’une nouvelle arme.', `FemaleText_lang`='Ma formation aux armes, je la dois principalement à l’entraînement d’Ilyenia Lunéclat, à la Terrasse des guerriers. Vous devriez aller la voir si vous désirez apprendre à vous servir d’une nouvelle arme.', `VerifiedBuild`=25549 WHERE (`ID`=7246 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Au long des millénaires, Ilyenia Lunéclat a appris à maîtriser nombre d’armes et elle propose désormais de former les autres. Vous la trouverez sur la Terrasse des guerriers si vous souhaitez vous entraîner.', `FemaleText_lang`='Au long des millénaires, Ilyenia Lunéclat a appris à maîtriser nombre d’armes et elle propose désormais de former les autres. Vous la trouverez sur la Terrasse des guerriers si vous souhaitez vous entraîner.', `VerifiedBuild`=25549 WHERE (`ID`=7245 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Maître d’armes', `FemaleText_lang`='Maître d’armes', `VerifiedBuild`=25549 WHERE (`ID`=7244 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Maître Woo Ping connaît presque toutes les armes créées en ce monde. Il est particulièrement redoutable en combat à l’épée. Il passe pas mal de temps à l’Arsenal de Weller, attendant de nouvelles livraisons d’armes, si vous voulez qu’il vous entraîne.', `FemaleText_lang`='Maître Woo Ping connaît presque toutes les armes créées en ce monde. Il est particulièrement redoutable en combat à l’épée. Il passe pas mal de temps à l’Arsenal de Weller, attendant de nouvelles livraisons d’armes, si vous voulez qu’il vous entraîne.', `VerifiedBuild`=25549 WHERE (`ID`=7243 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’endurance de Woo Ping est tout simplement incroyable. Quand je l’ai observé s’entraîner pendant des heures d’affilée, j’avais vraiment mal pour le mannequin d’entraînement. Je ne connais personne de mieux placé pour vous entraîner au combat armé.', `FemaleText_lang`='L’endurance de Woo Ping est tout simplement incroyable. Quand je l’ai observé s’entraîner pendant des heures d’affilée, j’avais vraiment mal pour le mannequin d’entraînement. Je ne connais personne de mieux placé pour vous entraîner au combat armé.', `VerifiedBuild`=25549 WHERE (`ID`=7242 AND `locale`='frFR');
