UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les furbolgs tombe-hiver qui résident ici, au Berceau-de-l’Hiver, furent naguère nos alliés... Mais tout a changé.$B$BSuivant les ordres étranges de leur Grand Chef, ils ont commencé à attaquer quiconque entrait en contact avec eux, y compris notre tribu. Ils restent entre eux désormais...', `VerifiedBuild`=25549 WHERE (`ID`=7140 AND `locale`='frFR');
