UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ma foi, vous avez peu de chances de trouver un tailleur ici. Forgefer en abrite quelques-uns, en revanche. Allez-y et demandez de l’aide à un garde.', `FemaleText_lang`='Ma foi, vous avez peu de chances de trouver un tailleur ici. Forgefer en abrite quelques-uns, en revanche. Allez-y et demandez de l’aide à un garde.', `VerifiedBuild`=25549 WHERE (`ID`=7059 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ah, Front-de-Pierre ne quitte pas beaucoup Forgefer ces temps-ci. Si vous voulez devenir tailleur, c''est lui qu''il faut aller voir à Forgefer.', `FemaleText_lang`='Ah, Front-de-Pierre ne quitte pas beaucoup Forgefer ces temps-ci. Si vous voulez devenir tailleur, c''est lui qu''il faut aller voir à Forgefer.', `VerifiedBuild`=25549 WHERE (`ID`=7058 AND `locale`='frFR');
