UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il n’y a pas de dépeceurs en Dun Morogh $gmon garçon : ma petite;, ils sont presque tous à Forgefer si c’est un apprentissage qui vous intéresse.', `FemaleText_lang`='Il n’y a pas de dépeceurs en Dun Morogh $gmon garçon:ma petite;, ils sont presque tous à Forgefer si c’est un apprentissage qui vous intéresse.', `VerifiedBuild`=25549 WHERE (`ID`=7056 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Un mineur ? Il suffit de demander où en trouver un ! Yarr, c’est lui que vous cherchez. Vous le trouverez au Dépôt de Grillacier.', `FemaleText_lang`='Un mineur ? Il suffit de demander où en trouver un ! Yarr, c’est lui que vous cherchez. Vous le trouverez au Dépôt de Grillacier.', `VerifiedBuild`=25549 WHERE (`ID`=7055 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous ne pensiez pas trouver une ville sans mineur, n’est-ce pas ? Yarr se trouve généralement au Dépôt de Grillacier, à l’extérieur de Kharanos.', `FemaleText_lang`='Vous ne pensiez pas trouver une ville sans mineur, n’est-ce pas ? Yarr se trouve généralement au Dépôt de Grillacier, à l’extérieur de Kharanos.', `VerifiedBuild`=25549 WHERE (`ID`=7054 AND `locale`='frFR');
