UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pour autant que je sache, il n’y a pas d’enchanteurs dans Dun Morogh. Il va falloir aller à Forgefer si vous voulez apprendre la profession d’enchanteur.', `FemaleText_lang`='Pour autant que je sache, il n’y a pas d’enchanteurs dans Dun Morogh. Il va falloir aller à Forgefer si vous voulez apprendre la profession d’enchanteur.', `VerifiedBuild`=25549 WHERE (`ID`=7042 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Gremlock n’est pas toujours bien chanceux en cuisine, mais il a de bonnes recettes qui méritent d’être apprises. Allez lui parler à la Distillerie Tonnebière et voyez ce qu’il peut vous enseigner.', `FemaleText_lang`='Gremlock n’est pas toujours bien chanceux en cuisine, mais il a de bonnes recettes qui méritent d’être apprises. Allez lui parler à la Distillerie Tonnebière et voyez ce qu’il peut vous enseigner.', `VerifiedBuild`=25549 WHERE (`ID`=7041 AND `locale`='frFR');
