UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez Hogral ? Avez-vous été à la taverne ? Och ! Si vous cherchez un voleur, et un nain en plus, commencez par l’auberge ! Allez-y sans tarder.', `FemaleText_lang`='Vous cherchez Hogral ? Avez-vous été à la taverne ? Och ! Si vous cherchez un voleur, et un nain en plus, commencez par l’auberge ! Allez-y sans tarder.', `VerifiedBuild`=25549 WHERE (`ID`=7015 AND `locale`='frFR');
