UPDATE `broadcast_text_locale` SET `MaleText_lang`='La race ne fait pas l’honneur, $r. Tant que vous serez sur mes terres, je vous demanderai de respecter ce mot d’ordre.$B$BJ’ai connu des orcs aussi honorables que bon nombre de chevaliers et des humains aussi vils et brutaux que les pires créatures du Fléau.$B$BMais je ne vous raconterai pas mes exploits de jeunesse ! Il y a tant à faire, si tel est votre désir.', `VerifiedBuild`=25549 WHERE (`ID`=6889 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=6888 AND `locale`='frFR');
