UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il y est parvenu. Il a rapidement gravi la hiérarchie du culte, et le roi-liche lui a donné l’immortalité. C’est ainsi qu’est né Ras Murmegivre, la liche.$B$BVous comprenez, à présent ?', `VerifiedBuild`=25549 WHERE (`ID`=6855 AND `locale`='frFR');
