UPDATE `broadcast_text_locale` SET `MaleText_lang`='Nous ne sommes pas vraiment discourtois, mais tout le monde est pressé, tout doit être parfait pour l’arrivée d’Uther. Ce n’est pas tous les jours que le Porteur de Lumière vient en ville.', `FemaleText_lang`='Nous ne sommes pas vraiment discourtois, mais tout le monde est pressé, tout doit être parfait pour l’arrivée d’Uther. Ce n’est pas tous les jours que le Porteur de Lumière vient en ville.', `VerifiedBuild`=25549 WHERE (`ID`=6820 AND `locale`='frFR');
