UPDATE `broadcast_text_locale` SET `MaleText_lang`='Rupert Boch est son nom. Il paraît qu’il est à l’étage, dans l’une des chambres de la Taverne des Pendus, au sud-est de la ville.', `FemaleText_lang`='Rupert Boch est son nom. Il paraît qu’il est à l’étage, dans l’une des chambres de la Taverne des Pendus, au sud-est de la ville.', `VerifiedBuild`=25549 WHERE (`ID`=6741 AND `locale`='frFR');
