UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je me reposerais volontiers moi aussi, une chopine à la main. Vous trouverez l’auberge dans l’angle nord-ouest de Tranchecolline. Passez le bonjour de ma part à l’aubergiste Grosk.', `FemaleText_lang`='Je me reposerais volontiers moi aussi, une chopine à la main. Vous trouverez l’auberge dans l’angle nord-ouest de Tranchecolline. Passez le bonjour de ma part à l’aubergiste Grosk.', `VerifiedBuild`=25549 WHERE (`ID`=6600 AND `locale`='frFR');
