UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai du travail, ça ne se voit pas ? Suivez la route vers le nord jusqu’à Orgrimmar et demandez à l’un des grunts. Vous ne pouvez pas rater la ville.', `FemaleText_lang`='J’ai du travail, ça ne se voit pas ? Suivez la route vers le nord jusqu’à Orgrimmar et demandez à l’un des grunts. Vous ne pouvez pas rater la ville.', `VerifiedBuild`=25549 WHERE (`ID`=6598 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous trouverez un maître des coursiers du vent à Orgrimmar. Suivez la route vers le nord et demandez à l’un des grunts d’Orgrimmar de vous donner plus de renseignements.', `FemaleText_lang`='Vous trouverez un maître des coursiers du vent à Orgrimmar. Suivez la route vers le nord et demandez à l’un des grunts d’Orgrimmar de vous donner plus de renseignements.', `VerifiedBuild`=25549 WHERE (`ID`=6597 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oui, je dois aller déposer des choses à la banque moi aussi. Vous la trouverez à Orgrimmar, en suivant la route vers le nord. Demandez à l’un des grunts sur place pour savoir où elle se trouve précisément.', `FemaleText_lang`='Oui, je dois aller déposer des choses à la banque moi aussi. Vous la trouverez à Orgrimmar, en suivant la route vers le nord. Demandez à l’un des grunts sur place pour savoir où elle se trouve précisément.', `VerifiedBuild`=25549 WHERE (`ID`=6596 AND `locale`='frFR');
