UPDATE `broadcast_text_locale` SET `MaleText_lang`='Zog zog, brave $c ! J’ai en ma possession les plus remarquables loups de monte. Vous ne trouverez nulle part d’animal plus endurant et mieux doté de l’instinct de survie ! Regardez par vous-même !', `FemaleText_lang`='Zog zog, brave $c ! J’ai en ma possession les plus remarquables loups de monte. Vous ne trouverez nulle part d’animal plus endurant et mieux doté de l’instinct de survie ! Regardez par vous-même !', `VerifiedBuild`=25549 WHERE (`ID`=6440 AND `locale`='frFR');
