UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oh, l’éternelle obsession des biens matériels. Ma foi, la fortune vous sourit, car vous trouverez un hôtel des ventes sur la Terrasse des marchands.', `FemaleText_lang`='Oh, l’éternelle obsession des biens matériels. Ma foi, la fortune vous sourit, car vous trouverez un hôtel des ventes sur la Terrasse des marchands.', `VerifiedBuild`=25549 WHERE (`ID`=6366 AND `locale`='frFR');
