UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il n’y a pas de meilleur endroit pour apprendre le secourisme que sous l’œil attentif d’Angela Leifeld, à la Cathédrale de la Lumière. \n\nPour y aller, cherchez les toits jaunes, ou la tour de la Cathédrale elle-même. On la voit d’à peu près partout dans la ville.', `FemaleText_lang`='Il n’y a pas de meilleur endroit pour apprendre le secourisme que sous l’œil attentif d’Angela Leifeld, à la Cathédrale de la Lumière. \n\nPour y aller, cherchez les toits jaunes, ou la tour de la Cathédrale elle-même. On la voit d’à peu près partout dans la ville.', `VerifiedBuild`=25549 WHERE (`ID`=6313 AND `locale`='frFR');
