UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez agi juste au moment où j’allais être jeté en pâture à ces bêtes. Je vous en remercie. Peut-être nous autres, les dragons bleus, pourrons-nous vous aider de quelque manière ?$B$BVous avez beaucoup marché, $r, vous avez beaucoup risqué. Irez-vous plus loin pour combattre Nefarian et sa légion de Rochenoire ?', `VerifiedBuild`=25549 WHERE (`ID`=6280 AND `locale`='frFR');
