UPDATE `broadcast_text_locale` SET `MaleText_lang`='Quand l’adversaire se rend, c’est moi qui gagne !', `FemaleText_lang`='Quand l’adversaire se rend, c’est moi qui gagne !', `VerifiedBuild`=25549 WHERE (`ID`=6071 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le chef de guerre m’a ordonné d’étudier toutes les sortes d’armes et d’armures. Il m’a envoyé ici, au creuset des cultures tauren et orc, dans les Tarides, pour y rencontrer autant de voyageurs que possible et pour découvrir les cultures des Tarides.$B$BIl pense qu’il y a quelque chose à apprendre même des cultures les plus pathétiques... comme celle des hurans ou des centaures.', `VerifiedBuild`=25549 WHERE (`ID`=6070 AND `locale`='frFR');
