UPDATE `broadcast_text_locale` SET `MaleText_lang`='Toujours attentifs à la protection du monde naturel, les druides sont guidés par l’archidruide Fandral Forteramure, qui réside dans l’enclave Cénarienne. Vous le trouverez, ainsi que les autres maîtres des druides, dans la zone nord de Darnassus.', `FemaleText_lang`='Toujours attentifs à la protection du monde naturel, les druides sont guidés par l’archidruide Fandral Forteramure, qui réside dans l’enclave Cénarienne. Vous le trouverez, ainsi que les autres maîtres des druides, dans la zone nord de Darnassus.', `VerifiedBuild`=25549 WHERE (`ID`=6068 AND `locale`='frFR');
