UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Écoutez vos anciens, $n. Si vous avez assez de force et de persévérance, il n’est pas de pouvoir que vous ne puissiez contrôler.', `VerifiedBuild`=25549 WHERE (`ID`=6023 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Dites à Lexlort que s’il veut l’information, tout ce qu’il a à faire, c’est payer ! Malheureusement, cela signifie qu’il ne peut pas me tuer s’il désire les informations, vu que j’ai brûlé les plans stratégiques...', `VerifiedBuild`=25549 WHERE (`ID`=6022 AND `locale`='frFR');
