UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Salutations, $n. Mon nom est Chronormu, mais vous pouvez m’appeler Chromie. Ces familiarités ne me dérangent pas.$B$BComment ai-je appris votre nom ? Étant l’un des dragons de bronze, je suis liée au fleuve du temps, et en quelque sorte nous nous sommes déjà rencontrés. Nous nous rencontrerons encore.', `VerifiedBuild`=25549 WHERE (`ID`=6018 AND `locale`='frFR');
