UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oui. Nefarian, descendant de l’Aile de mort, dirige désormais le Pic. Rend est sous le contrôle du dragon.$B$BSi seulement vous parveniez à passer par les Halls de l’Ascension.$B$B<Eitrigg soupire.>$B$BHélas, seuls ceux qui sont jugés dignes par les dragons noirs gagnent le droit d’y monter.', `VerifiedBuild`=25549 WHERE (`ID`=6001 AND `locale`='frFR');
