UPDATE `broadcast_text_locale` SET `MaleText_lang`='On apprend vite, à ce que je vois, et vous avez quelques bases comme forgeron. Je vous embauche quand vous voulez. Mais je vois que vous voulez encore en apprendre plus. Allez parler à Bengus Forge-profonde, ce n’est pas quelqu’un de facile mais c’est l’un des meilleurs maîtres.', `VerifiedBuild`=25549 WHERE (`ID`=5787 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Salut ! Je suis tout à fait d’accord pour vous enseigner deux ou trois choses sur la forge. Prenez un tablier et un marteau et voyons ce que vous savez faire, d’accord ?', `VerifiedBuild`=25549 WHERE (`ID`=5786 AND `locale`='frFR');
