UPDATE `broadcast_text_locale` SET `MaleText_lang`='Eh non $gmon gars:ma petite;, vous n’êtes pas à la hauteur pour des leçons avec moi. Allez voir mon fils Groum, ça lui fera plaisir d’avoir un nouvel apprenti.', `VerifiedBuild`=25549 WHERE (`ID`=5784 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='La vie d’un forgeron n’est pas simple, mais ça met de l’acier dans les os et du feu dans le cœur ! Mon père était forgeron, et mon grand-père avant lui, dans les forges sous Grim Batol. Et maintenant mon fils suit mes traces, je suis bien fier de lui.', `VerifiedBuild`=25549 WHERE (`ID`=5783 AND `locale`='frFR');
