UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai perdu la Cache de Mau’ari. Que puis-je faire ?', `FemaleText_lang`='J’ai perdu la Cache de Mau’ari. Que puis-je faire ?', `VerifiedBuild`=25549 WHERE (`ID`=5758 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='L’E’ko est la forme non focalisée du pouvoir surnaturel, Juju est son essence concentrée. Grâce à une intense incantation, je peux transformer l’E’ko en Juju. Une fois qu’il est Juju, vous pouvez utiliser la Cache de Mau’ari pour réfléchir sur vous ses pouvoirs.', `VerifiedBuild`=25549 WHERE (`ID`=5757 AND `locale`='frFR');
