UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous avez beaucoup appris, plus que je ne suis capable d’enseigner. Allez voir James Van Brunt, il vous apprendra ce que je ne puis.', `VerifiedBuild`=25549 WHERE (`ID`=5754 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='N’essayez pas de tuer l’enclume avec le marteau. Essayez de créer une arme pour vaincre vos ennemis. Je vais vous montrer en quoi vous vous trompez.', `VerifiedBuild`=25549 WHERE (`ID`=5753 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’espère un jour forger des armes et des armures avec les ossements de mes ennemis.', `VerifiedBuild`=25549 WHERE (`ID`=5752 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous avez bien appris, mon enfant. Allez à Fossoyeuse, trouvez un forgeron nommé James Van Brunt. Il en sait bien plus long que moi. Je crois savoir qu’il passe tout son temps près du hall d’entraînement des guerriers, forgeant leurs armes et leurs armures.', `VerifiedBuild`=25549 WHERE (`ID`=5751 AND `locale`='frFR');
