UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Vous me coûtez un temps précieux à m’interrompre comme ça. Vous avez intérêt à avoir une bonne raison.', `VerifiedBuild`=25549 WHERE (`ID`=5749 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Tout n’est pas perdu ! Combattez sans crainte ces bêtes. Je soignerai vos blessures, je réparerai vos os. Qu’une force nouvelle vous anime, héros !', `VerifiedBuild`=25549 WHERE (`ID`=5748 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suppose que les esprits vous aiment plus que moi, je n’ai toujours pas entendu leur appel mais vous semblez avoir bien profité de leurs leçons. Allez parler à Karn, il sera enchanté de rencontrer quelqu’un qui entend également les esprits.', `VerifiedBuild`=25549 WHERE (`ID`=5747 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Karn dit que nous devons écouter les esprits de la forge et de l’acier, et qu’ils nous guideront. Je n’entends rien qu’un cliquetis. Tenez, prenez un marteau et essayons d’entendre les esprits ensemble.', `VerifiedBuild`=25549 WHERE (`ID`=5746 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’écoute, j’écoute encore, mais je n’entends pas les esprits dont parle Karn.', `VerifiedBuild`=25549 WHERE (`ID`=5745 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous apprenez vite, c’est une bonne chose. Faites le travail correctement, mettez-y le temps qu’il faut. Mais je crains de devoir vous envoyer à Grond si vous voulez progresser. Apprenez ce qu’il a à enseigner mais n’écoutez pas ses grommellements. Il est comme ça quand les filles de Saru se moquent de lui.', `VerifiedBuild`=25549 WHERE (`ID`=5744 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je peux vous montrer ce que vous voulez savoir, mais il faut de la patience. Prenez le temps quand vous travaillez l’acier de sentir comment il prend forme sous votre marteau. Faites un avec l’acier, et alors vous comprendrez.', `VerifiedBuild`=25549 WHERE (`ID`=5743 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5742 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pas mal. Allez parler à Grond, il vient de s’installer à Orgrimmar pour étudier avec Saru. Cherchez-le dans le quartier des guerriers, près de l’enclume de Saru. Oh, et il vous demandera de faire vos preuves, alors vous feriez mieux de vous préparer !', `VerifiedBuild`=25549 WHERE (`ID`=5741 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5740 AND `locale`='frFR');
