UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous êtes bien meilleur forgeron que moi. Mais je ne l’avouerai jamais publiquement, croyez-moi. Allez parler à Therum Forge-profonde. Si quelqu’un peut vous en apprendre plus, c’est bien lui.', `VerifiedBuild`=25549 WHERE (`ID`=5738 AND `locale`='frFR');
