UPDATE `broadcast_text_locale` SET `MaleText_lang`='Où puis-je trouver de l’E’ko ?', `FemaleText_lang`='Où puis-je trouver de l’E’ko ?', `VerifiedBuild`=25549 WHERE (`ID`=5731 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ma foi, vos compétences sont supérieures aux miennes. Pourquoi ne pas aller voir mon vieil ami Rotgath Barbe-de-Pierre. Il est resté à Forgefer lorsque j’ai rejoint l’armée de Jaina. Il pourra sûrement vous enseigner quelque chose, ou vous mettra sur la route de quelqu’un qui le pourra. S’il est toujours dans le coin, vous le trouverez sûrement à la Grande Forge.', `VerifiedBuild`=25549 WHERE (`ID`=5730 AND `locale`='frFR');
