UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Gadgetzan est un patelin charmant comparé à Un’Goro, mais j’ai de bons amis qui comptent sur nous pour les ravitailler. Si vous vous sentez d’attaque pour y aller, Dadanga et moi aussi. Allons-y !', `VerifiedBuild`=25549 WHERE (`ID`=5701 AND `locale`='frFR');
