UPDATE `broadcast_text_locale` SET `FemaleText_lang`='La Cache de Mau’ari détient de grands secrets... Les éclats utilisés dans la fabrication ont des propriétés réflexives et vous pouvez utiliser sa surface lumineuse pour siphonner la puissance d’autres choses et les réfléchir sur vous-même.$B$BGardez le charme dans votre inventaire pour collecter l’e’ko, la puissance spirituelle des bêtes que vous combattez. Quand vous trouverez de l’e’ko, rapportez-en à Mau’ari.', `VerifiedBuild`=25549 WHERE (`ID`=5699 AND `locale`='frFR');
