UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je devrais peut-être vous dire pourquoi je suis ici.$B$BVous savez quelque chose sur l’Aspect qui se fait appeler l’Aile de mort ? Ou sa progéniture, Nefarian et Onyxia ?', `VerifiedBuild`=25549 WHERE (`ID`=5572 AND `locale`='frFR');
