UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Les steppes Ardentes sont un endroit dangereux, mais les érudits dans mon genre feraient n’importe quoi pour augmenter leurs connaissances.', `VerifiedBuild`=25549 WHERE (`ID`=5552 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Salut $n !$B$BJe dois travailler à mes mécanismes, mais au bout du compte... Je vais avoir besoin de quelqu’un pour me rapporter des œufs de dragon !', `VerifiedBuild`=25549 WHERE (`ID`=5551 AND `locale`='frFR');
