UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il me semble que du courrier a été apporté il n’y a pas longtemps. Vous trouverez la boîte aux lettres à l’extérieur de la banque des Pitons-du-Tonnerre, sur la Cime inférieure.', `FemaleText_lang`='Il me semble que du courrier a été apporté il n’y a pas longtemps. Vous trouverez la boîte aux lettres à l’extérieur de la banque des Pitons-du-Tonnerre, sur la Cime inférieure.', `VerifiedBuild`=25549 WHERE (`ID`=5501 AND `locale`='frFR');
