UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’aubergiste Pala vous aidera à reposer votre corps et votre esprit. Vous la trouverez dans le bâtiment au sud de la banque, sur la Cime inférieure.', `FemaleText_lang`='L’aubergiste Pala vous aidera à reposer votre corps et votre esprit. Vous la trouverez dans le bâtiment au sud de la banque, sur la Cime inférieure.', `VerifiedBuild`=25549 WHERE (`ID`=5499 AND `locale`='frFR');
