UPDATE `broadcast_text_locale` SET `MaleText_lang`='Force du corps et de l’esprit. Il n’est pas de combinaison plus solide ! Votre destin vous conduit vers Sark Totem-de-rage, dans le Hall des chasseurs.', `FemaleText_lang`='Force du corps et de l’esprit. Il n’est pas de combinaison plus solide ! Votre destin vous conduit vers Sark Totem-de-rage, dans le Hall des chasseurs.', `VerifiedBuild`=25549 WHERE (`ID`=5496 AND `locale`='frFR');
