UPDATE `broadcast_text_locale` SET `MaleText_lang`='Habiller la tribu est un travail aussi important qu’un autre. Cherchez Tepa aux Armuriers des Pitons-du-Tonnerre. Elle sait se servir d’une aiguille comme personne.', `FemaleText_lang`='Habiller la tribu est un travail aussi important qu’un autre. Cherchez Tepa aux Armuriers des Pitons-du-Tonnerre. Elle sait se servir d’une aiguille comme personne.', `VerifiedBuild`=25549 WHERE (`ID`=5494 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous êtes en harmonie avec la nature et vous n’avez que vos compétences pour survivre. C’est ce que voulait la Terre-Mère. Vous trouverez Bale sur la cime des Chasseurs.', `FemaleText_lang`='Vous êtes en harmonie avec la nature et vous n’avez que vos compétences pour survivre. C’est ce que voulait la Terre-Mère. Vous trouverez Bale sur la cime des Chasseurs.', `VerifiedBuild`=25549 WHERE (`ID`=5493 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le moindre petit lambeau utilisé à bon escient évite le gaspillage et nous rapproche de la Terre-Mère. Mooranta peut vous montrer la voie. Vous la trouverez juste à l’extérieur de la boutique des Armuriers des Pitons-du-Tonnerre, sur la Côte centrale.', `FemaleText_lang`='Le moindre petit lambeau utilisé à bon escient évite le gaspillage et nous rapproche de la Terre-Mère. Mooranta peut vous montrer la voie. Vous la trouverez juste à l’extérieur de la boutique des Armuriers des Pitons-du-Tonnerre, sur la Côte centrale.', `VerifiedBuild`=25549 WHERE (`ID`=5492 AND `locale`='frFR');
