UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5473 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pourquoi quitter ces rivages ensoleillés et ces eaux bleues cristallines ? Je me le demande. C’est un vrai paradis ici. Mais ne le dites pas à mon frère Zapetta, il est déjà assez amer d’être coincé à Tirisfal. Ce zeppelin va à Orgrimmar, vous n’aurez donc pas à l’écouter pleurnicher. Mais si vous allez à Tirisfal un jour prochain, souvenez-vous de mes conseils et ne l’encouragez pas à vous parler.', `FemaleText_lang`='Pourquoi quitter ces rivages ensoleillés et ces eaux bleues cristallines ? Je me le demande. C’est un vrai paradis ici. Mais ne le dites pas à mon frère Zapetta, il est déjà assez amer d’être coincé à Tirisfal. Ce zeppelin va à Orgrimmar, vous n’aurez donc pas à l’écouter pleurnicher. Mais si vous allez à Tirisfal un jour prochain, souvenez-vous de mes conseils et ne l’encouragez pas à vous parler.', `VerifiedBuild`=25549 WHERE (`ID`=5472 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5471 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Cueillir et utiliser des herbes, c’est la spécialité de Firodren Mandelune. Cherchez-le dans les Jardins du Temple, dans le sud-ouest de Darnassus.', `FemaleText_lang`='Cueillir et utiliser des herbes, c’est la spécialité de Firodren Mandelune. Cherchez-le dans les Jardins du Temple, dans le sud-ouest de Darnassus.', `VerifiedBuild`=25549 WHERE (`ID`=5470 AND `locale`='frFR');
