UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5452 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Non, pas que je sache. C’est essentiellement un problème de région. Certaines races les appellent gelées, d’autres limons. Question de préférence.$B$BÀ chaque fois que j’en ai rencontré, il s’agissait en fait des mêmes créatures. Les différences semblent relever de l’environnement, c’est pourquoi nous avons besoin d’un échantillon pur.', `VerifiedBuild`=25549 WHERE (`ID`=5451 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5450 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Il doit y avoir un endroit à Azeroth où l’on pourrait trouver des limons non corrompus par le Fléau ou par autre chose. Mais où ?!', `VerifiedBuild`=25549 WHERE (`ID`=5449 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Regardez ces échantillons ! Qu’est-ce que ça veut dire ? Je vais avoir besoin de temps pour déchiffrer toutes ces informations. Et il me faudra d’autres informations. Des informations que je ne puis obtenir... Enfer ! Réfléchis un peu, Laris !$B$BQu’est-ce que tu vas faire ? Quoi ?!$B$BIl doit bien y avoir une solution !', `VerifiedBuild`=25549 WHERE (`ID`=5448 AND `locale`='frFR');
