UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Voici le chemin permettant de sortir d’Un’Goro ! Nous avons réussi ! Nous n’avons plus qu’à affronter le désert de Tanaris à présent.', `VerifiedBuild`=25549 WHERE (`ID`=5439 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Voici la paroi est de la montagne. Je vais vers le sud maintenant, essayez de suivre. On n’est pas encore sortis de l’auberge !', `VerifiedBuild`=25549 WHERE (`ID`=5437 AND `locale`='frFR');
