UPDATE `broadcast_text_locale` SET `MaleText_lang`='Salut, $gétranger:étrangère; ! Bienvenue au majestueux et sauvage Cratère d’Un’Goro !$B$BJe me nomme Williden Marshal. Ma sœur, mes compagnons et moi avons créé les Expéditions Marshal : des scientifiques et des explorateurs s’aventurant dans les grandes régions inconnues d’Azeroth.', `VerifiedBuild`=25549 WHERE (`ID`=5435 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Oh, bien le bonjour ! Je suis Hol’anyee, la scientifique et biologiste en charge des Expéditions Marshal. Mon frère et moi, ainsi que nos compagnons, traversons Azeroth en explorant sa beauté sauvage et encore vierge. C’est si passionnant... Mais je crains que nous ne nous soyons montrés trop passionnés cette fois...', `VerifiedBuild`=25549 WHERE (`ID`=5434 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Pour l’amour de tout ce qui est sacré et chéri, dites-moi que vous êtes $gvenu:venue; nous délivrer de ces terres maudites. Bien que je sois avec les Expéditions Marshal, je vous donnerais mes propres dents en or pour grimper dans votre sac à dos et quitter cet endroit.', `VerifiedBuild`=25549 WHERE (`ID`=5433 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5432 AND `locale`='frFR');
