UPDATE `broadcast_text_locale` SET `MaleText_lang`='L’empereur Thaurissan ne veut pas être dérangé ! Faites demi-tour ou affrontez votre fin, puérils mortels !', `VerifiedBuild`=25549 WHERE (`ID`=5430 AND `locale`='frFR');
