UPDATE `broadcast_text_locale` SET `FemaleText_lang`='J’ai observé quatre espèces différentes de plantes affectées par la corruption : la fleur-de-chant, la fleur-de-vent, la navetille et le dragon nocturne. La fleur-de-chant et la fleur-de-vent sont communes dans Gangrebois, les deux autres sont plus rares. Toutes sont vitales pour l’écosystème de Gangrebois.', `VerifiedBuild`=25549 WHERE (`ID`=5386 AND `locale`='frFR');
