UPDATE `broadcast_text_locale` SET `MaleText_lang`='Aucune créature dans la forêt ne peut échapper à Corand, qui sait pister comme personne. Vous devriez écouter ses enseignements si vous souhaitez réussir un tant soit peu. \n\nJe vous libérerai de la corvée de le pister et je vais marquer sa position sur la carte, là, dans l''Enclave cénarienne.', `FemaleText_lang`='Aucune créature dans la forêt ne peut échapper à Corand, qui sait pister comme personne. Vous devriez écouter ses enseignements si vous souhaitez réussir un tant soit peu. \n\nJe vous libérerai de la corvée de le pister et je vais marquer sa position sur la carte, là, dans l''Enclave cénarienne.', `VerifiedBuild`=25549 WHERE (`ID`=5383 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=5382 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez sans doute Me’Lynn si vous avez quelque espoir de devenir tailleur. Elle se trouve à la terrasse des Artisans, dans la zone nord-est de Darnassus.', `FemaleText_lang`='Vous cherchez sans doute Me’Lynn si vous avez quelque espoir de devenir tailleur. Elle se trouve à la terrasse des Artisans, dans la zone nord-est de Darnassus.', `VerifiedBuild`=25549 WHERE (`ID`=5381 AND `locale`='frFR');
