UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le pouvoir d’Élune vous commande ! Le pouvoir d’Élune vous commande ! \n\nAllez à présent ! Cherchez Jandria dans le Hall central du temple de la Lune, dans la partie sud de Darnassus !', `FemaleText_lang`='Le pouvoir d’Élune vous commande ! Le pouvoir d’Élune vous commande ! \n\nAllez à présent ! Cherchez Jandria dans le Hall central du temple de la Lune, dans la partie sud de Darnassus !', `VerifiedBuild`=25549 WHERE (`ID`=5346 AND `locale`='frFR');
