UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Mon nom est J.D., et je ne sais pas trop comment je suis arrivée ici, mais je sais que c’est ma maison maintenant !$B$BJe passe tout mon temps à étudier les étranges cristaux que l’on trouve partout dans le cratère. Vous avez dû en voir en venant. Vous n’en auriez pas ramassé, par hasard ?', `VerifiedBuild`=25549 WHERE (`ID`=5171 AND `locale`='frFR');
