UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ce Jormund Front-de-Pierre a un don pour l''aiguille, pas de doute. Si vous avez besoin de leçons, vous le trouverez aux Vêtements de Front-de-Pierre, au nord de la Grande Forge.', `FemaleText_lang`='Ce Jormund Front-de-Pierre a un don pour l''aiguille, pas de doute. Si vous avez besoin de leçons, vous le trouverez aux Vêtements de Front-de-Pierre, au nord de la Grande Forge.', `VerifiedBuild`=25549 WHERE (`ID`=5145 AND `locale`='frFR');
