UPDATE `broadcast_text_locale` SET `MaleText_lang`='Si nous avons des maîtres des mineurs ici ? Et où croyez-vous vous trouver ?\n\nVous trouverez les meilleurs mineurs de tout Dun Morogh dans la maison Minage et joaillerie de la montagne profonde, au nord de la Grande Forge. Là, Geofram Rochorteil vous enseignera l’art véritable de la mine.', `FemaleText_lang`='Si nous avons des maîtres des mineurs ici ? Et où croyez-vous vous trouver ?\n\nVous trouverez les meilleurs mineurs de tout Dun Morogh dans la maison Minage et joaillerie de la montagne profonde, au nord de la Grande Forge. Là, Geofram Rochorteil vous enseignera l’art véritable de la mine.', `VerifiedBuild`=25549 WHERE (`ID`=5139 AND `locale`='frFR');
