UPDATE `broadcast_text_locale` SET `MaleText_lang`='Fimble Finfuseau a une échoppe au nord-ouest de la Grande Forge. Je parie qu’il pourrait vous montrer comment faire de belles armures.', `FemaleText_lang`='Fimble Finfuseau a une échoppe au nord-ouest de la Grande Forge. Je parie qu’il pourrait vous montrer comment faire de belles armures.', `VerifiedBuild`=25549 WHERE (`ID`=5135 AND `locale`='frFR');
