UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oh ! Vous voulez apprendre à ramasser des pâquerettes ? Ah, je plaisante ! \n\nC’est une respectable profession, et Reyna Branchepierre peut vous montrer en quoi elle consiste. Elle travaille au Médecin de Forgefer, au sud de la Grande Forge.', `FemaleText_lang`='Oh ! Vous voulez apprendre à ramasser des pâquerettes ? Ah, je plaisante ! \n\nC’est une respectable profession, et Reyna Branchepierre peut vous montrer en quoi elle consiste. Elle travaille au Médecin de Forgefer, au sud de la Grande Forge.', `VerifiedBuild`=25549 WHERE (`ID`=5132 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les fleurs, les graines, tout ça ? C’est la branche de Reyna Branchepierre, si j’ose dire ! Vous la trouverez, les doigts dans l’humus, au Médecin de Forgefer, au sud de la Grande Forge.', `FemaleText_lang`='Les fleurs, les graines, tout ça ? C’est la branche de Reyna Branchepierre, si j’ose dire ! Vous la trouverez, les doigts dans l’humus, au Médecin de Forgefer, au sud de la Grande Forge.', `VerifiedBuild`=25549 WHERE (`ID`=5131 AND `locale`='frFR');
