UPDATE `broadcast_text_locale` SET `MaleText_lang`='Le secourisme ? C’est bien utile ! Notre maître local, Nissa Pierre-de-feu, peut vous montrer comment l’on fait. Cherchez-la au sud de la Grande Forge, au Médecin de Forgefer.', `FemaleText_lang`='Le secourisme ? C’est bien utile ! Notre maître local, Nissa Pierre-de-feu, peut vous montrer comment l’on fait. Cherchez-la au sud de la Grande Forge, au Médecin de Forgefer.', `VerifiedBuild`=25549 WHERE (`ID`=5126 AND `locale`='frFR');
