UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez un maître des alchimistes ? Ça tombe bien, je viens d’en voir un. Vous trouverez Mme Baiedesbulles à Brikabrok, là où les gnomes s’assemblent. \n\n<soupir> Mais pourquoi je n’ai pas pris la potion bleue ?', `FemaleText_lang`='Vous cherchez un maître des alchimistes ? Ça tombe bien, je viens d’en voir un. Vous trouverez Mme Baiedesbulles à Brikabrok, là où les gnomes s’assemblent. \n\n<soupir> Mais pourquoi je n’ai pas pris la potion bleue ?', `VerifiedBuild`=25549 WHERE (`ID`=5116 AND `locale`='frFR');
