UPDATE `broadcast_text_locale` SET `MaleText_lang`='Och ! Vous voulez devenir guerrier, hein ? Kelstrum Brise-Pierres vous y aidera. Rendez-vous à la Salle d’armes, à l’est des portes de Forgefer.', `FemaleText_lang`='Och ! Vous voulez devenir guerrier, hein ? Kelstrum Brise-Pierres vous y aidera. Rendez-vous à la Salle d’armes, à l’est des portes de Forgefer.', `VerifiedBuild`=25549 WHERE (`ID`=5111 AND `locale`='frFR');
