UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous trouverez à vous perfectionner dans les arts magiques au Hall des mystères, au nord des portes de Forgefer. Juli Cyclobouilloire s’y trouve toujours, le nez dans un bouquin.', `FemaleText_lang`='Vous trouverez à vous perfectionner dans les arts magiques au Hall des mystères, au nord des portes de Forgefer. Juli Cyclobouilloire s’y trouve toujours, le nez dans un bouquin.', `VerifiedBuild`=25549 WHERE (`ID`=5099 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Cette petite Bink, là-bas dans le Hall des mystères, serait sans doute capable de satisfaire tous vos besoins en matière de magie. \n\nLe Hall des mystères est au nord des portes de Forgefer.', `FemaleText_lang`='Cette petite Bink, là-bas dans le Hall des mystères, serait sans doute capable de satisfaire tous vos besoins en matière de magie. \n\nLe Hall des mystères est au nord des portes de Forgefer.', `VerifiedBuild`=25549 WHERE (`ID`=5098 AND `locale`='frFR');
