UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’ai entendu Regnus Tonnegranit, à la Salle d’armes. Il se vantait d’un nouveau trophée l’autre jour. Si vous voulez être $gformé:formée; par un chasseur de talent, Regnus est l’homme à voir.', `FemaleText_lang`='J’ai entendu Regnus Tonnegranit, à la Salle d’armes. Il se vantait d’un nouveau trophée l’autre jour. Si vous voulez être $gformé:formée; par un chasseur de talent, Regnus est l’homme à voir.', `VerifiedBuild`=25549 WHERE (`ID`=5096 AND `locale`='frFR');
