UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous pouvez trouver une boîte aux lettres à droite de la Taverne de Brûlepierre. C’est au nord des portes de Forgefer.', `FemaleText_lang`='Vous pouvez trouver une boîte aux lettres à droite de la Taverne de Brûlepierre. C’est au nord des portes de Forgefer.', `VerifiedBuild`=25549 WHERE (`ID`=5094 AND `locale`='frFR');
