UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ah, rien ne vaut une bonne promenade en griffon, pas vrai ? Les elfes de la nuit peuvent se garder leurs hippos, pour moi rien de tel que les bons vieux griffons ! \n\nMais je ne veux pas vous retarder, allez voir Gryth Thurden à l''est de la Grande Forge. Il vous mettra sur la route.', `FemaleText_lang`='Ah, rien ne vaut une bonne promenade en griffon, pas vrai ? Les elfes de la nuit peuvent se garder leurs hippos, pour moi rien de tel que les bons vieux griffons ! \n\nMais je ne veux pas vous retarder, allez voir Gryth Thurden à l''est de la Grande Forge. Il vous mettra sur la route.', `VerifiedBuild`=25549 WHERE (`ID`=5085 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous voulez faire une promenade en griffon, hein ? Gryth Thurden est celui qu’il faut voir !\n\nVous le trouverez à l’est de la Grande Forge, au milieu de Forgefer.', `FemaleText_lang`='Vous voulez faire une promenade en griffon, hein ? Gryth Thurden est celui qu’il faut voir !\n\nVous le trouverez à l’est de la Grande Forge, au milieu de Forgefer.', `VerifiedBuild`=25549 WHERE (`ID`=5083 AND `locale`='frFR');
