UPDATE `broadcast_text_locale` SET `MaleText_lang`='Voici le mode de transport le plus efficace et le plus moderne qui soit. Quoi ? Le Tram des profondeurs ? Les gnomes ? Écoutez-moi bien : si vous croyez à ces âneries, j’ai une statue à vous vendre à Strangleronce. Alors, vous voulez marcher jusqu’à Grom’Gol ou prendre cette merveilleuse machine volante ? À vous de voir.', `VerifiedBuild`=25549 WHERE (`ID`=5052 AND `locale`='frFR');
