UPDATE `broadcast_text_locale` SET `MaleText_lang`='Trois cents ? Alors les Sombrefers l’ont tué avant de le transporter dans les Profondeurs ?', `FemaleText_lang`='Trois cents ? Alors les Sombrefers l’ont tué avant de le transporter dans les Profondeurs ?', `VerifiedBuild`=25549 WHERE (`ID`=5030 AND `locale`='frFR');
