UPDATE `broadcast_text_locale` SET `MaleText_lang`='Mon père m’a dit qu’il y aurait des jours comme ça, où $gun étranger:une étrangère; s’arrêterait pour me parler et où je ne pourrais pas $gle:la; tuer.', `FemaleText_lang`='Mon père m’a dit qu’il y aurait des jours comme ça, où $gun étranger:une étrangère; s’arrêterait pour me parler et où je ne pourrais pas $gle:la; tuer.', `VerifiedBuild`=25549 WHERE (`ID`=4956 AND `locale`='frFR');
