UPDATE `broadcast_text_locale` SET `MaleText_lang`='Trouvez le hall des Braves dans la vallée de l’Honneur et parlez à Grezz Ragepoing. Faites-leur savoir que je me présenterai après mon quart.', `FemaleText_lang`='Trouvez le hall des Braves dans la vallée de l’Honneur et parlez à Grezz Ragepoing. Faites-leur savoir que je me présenterai après mon quart.', `VerifiedBuild`=25549 WHERE (`ID`=4818 AND `locale`='frFR');
