UPDATE `broadcast_text_locale` SET `MaleText_lang`='On vient à peine de se débarrasser de la Légion ardente, et vous recommencez à jouer avec les démons ? Cherchez l’Enclave de Sombrefeu dans la caverne souterraine nommée la Faille de l’Ombre. Vous trouverez un tunnel qui y mène depuis la Herse.', `FemaleText_lang`='On vient à peine de se débarrasser de la Légion ardente, et vous recommencez à jouer avec les démons ? Cherchez l’Enclave de Sombrefeu dans la caverne souterraine nommée la Faille de l’Ombre. Vous trouverez un tunnel qui y mène depuis la Herse.', `VerifiedBuild`=25549 WHERE (`ID`=4816 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez Grol’dar et l’Enclave de Sombrefeu ? Vous les trouverez dans la caverne souterraine appelée Faille de l’Ombre. Deux tunnels mènent à cette grotte, l’un au sud de la vallée de la Sagesse, l’autre depuis la Herse.', `FemaleText_lang`='Vous cherchez Grol’dar et l’Enclave de Sombrefeu ? Vous les trouverez dans la caverne souterraine appelée Faille de l’Ombre. Deux tunnels mènent à cette grotte, l’un au sud de la vallée de la Sagesse, l’autre depuis la Herse.', `VerifiedBuild`=25549 WHERE (`ID`=4815 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Que je ne vous y prenne pas à voler quoi que ce soit ! Cherchez Shenthul et sa Confrérie Ombrevive dans les profondeurs de la Faille de l’Ombre. Trouvez le tunnel qui descend vers le sud de la vallée de la Sagesse.', `FemaleText_lang`='Que je ne vous y prenne pas à voler quoi que ce soit ! Cherchez Shenthul et sa Confrérie Ombrevive dans les profondeurs de la Faille de l’Ombre. Trouvez le tunnel qui descend vers le sud de la vallée de la Sagesse.', `VerifiedBuild`=25549 WHERE (`ID`=4814 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Vous cherchez Shenthul de la Confrérie Ombrevive, hein ? Dans la Herse, après Récupération Droffers et fils, cherchez un tunnel qui mène à la Faille de l’Ombre.', `FemaleText_lang`='Vous cherchez Shenthul de la Confrérie Ombrevive, hein ? Dans la Herse, après Récupération Droffers et fils, cherchez un tunnel qui mène à la Faille de l’Ombre.', `VerifiedBuild`=25549 WHERE (`ID`=4813 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Votre quête est presque achevée. Cherchez votre vérité dans la salle d’entrée de la Forteresse de Thrall, dans la vallée de la Sagesse.', `FemaleText_lang`='Votre quête est presque achevée. Cherchez votre vérité dans la salle d’entrée de la Forteresse de Thrall, dans la vallée de la Sagesse.', `VerifiedBuild`=25549 WHERE (`ID`=4812 AND `locale`='frFR');
