UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les soins, c’est pour ceux qui ne supportent pas la douleur. Mais si vous le voulez vraiment, cherchez l’Autel des esprits sur le lac de la vallée des Esprits, au-dessus de la vallée de la Force, à l’ouest.', `FemaleText_lang`='Les soins, c’est pour ceux qui ne supportent pas la douleur. Mais si vous le voulez vraiment, cherchez l’Autel des esprits sur le lac de la vallée des Esprits, au-dessus de la vallée de la Force, à l’ouest.', `VerifiedBuild`=25549 WHERE (`ID`=4810 AND `locale`='frFR');
