UPDATE `broadcast_text_locale` SET `MaleText_lang`='Des vêtements ? Ça ne vous protégera pas contre les lames d’acier ! Enfin, si vous êtes $gsûr:sûre; de vouloir devenir tailleur, cherchez la Friperie de Magar dans la Herse.', `FemaleText_lang`='Des vêtements ? Ça ne vous protégera pas contre les lames d’acier ! Enfin, si vous êtes $gsûr:sûre; de vouloir devenir tailleur, cherchez la Friperie de Magar dans la Herse.', `VerifiedBuild`=25549 WHERE (`ID`=4789 AND `locale`='frFR');
