UPDATE `broadcast_text_locale` SET `MaleText_lang`='Denni’ka peut vous apprendre à rester au chaud. Cherchez-la à la Survie du plus fort, une hutte sur la berge du lac, près de l’Autel des esprits. Dirigez-vous vers l’ouest de la vallée de la Force, en haut.', `FemaleText_lang`='Denni’ka peut vous apprendre à rester au chaud. Cherchez-la à la Survie du plus fort, une hutte sur la berge du lac, près de l’Autel des esprits. Dirigez-vous vers l’ouest de la vallée de la Force, en haut.', `VerifiedBuild`=25549 WHERE (`ID`=4787 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je préfère ma nourriture crue, mais si vous aimez les plats mitonnés, Denni’ka peut vous apprendre à allumer un feu. Vous la trouverez à la Survie du plus fort, une hutte sur la berge du lac, près de l’Autel des esprits. Cherchez en haut, à l’ouest de la vallée de la Force.', `FemaleText_lang`='Je préfère ma nourriture crue, mais si vous aimez les plats mitonnés, Denni’ka peut vous apprendre à allumer un feu. Vous la trouverez à la Survie du plus fort, une hutte sur la berge du lac, près de l’Autel des esprits. Cherchez en haut, à l’ouest de la vallée de la Force.', `VerifiedBuild`=25549 WHERE (`ID`=4786 AND `locale`='frFR');
