UPDATE `broadcast_text_locale` SET `MaleText_lang`='Elle se trouve maintenant aux côtés de l’empereur Thaurissan. Elle est victime d’un puissant charme de contrôle mental... Et moi je suis là, complètement impuissant…', `VerifiedBuild`=25549 WHERE (`ID`=4749 AND `locale`='frFR');
