UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je ne comprends pas les officiels de Hurlevent. Envoyer comme ça notre armée à l’autre bout du monde… Alors que l’ennemi est à nos portes !$B$BAvec les voleurs qui viennent de la marche de l’Ouest et les gnolls qui dévalent de l’est et de l’ouest, c’est un miracle que Hurlevent ne soit pas encore assiégé.', `VerifiedBuild`=25549 WHERE (`ID`=4637 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Si vous êtes ici pour me faire perdre mon temps, alors c’est le temps du Cercle cénarien que vous gaspillez. Dans votre intérêt, espérons que vous n’êtes pas assez $gsot:sotte; pour cela.', `VerifiedBuild`=25549 WHERE (`ID`=4636 AND `locale`='frFR');
