UPDATE `broadcast_text_locale` SET `MaleText_lang`='Je suis le Maître-bricoleur Suprétincelle, et le principal architecte des principes gnomes du monde contemporain. Il est de mon devoir de m’assurer que le pouvoir d’invention continue à briller ici plus qu’ailleurs !$B$BPar ailleurs, si vous connaissez un mécanisme pour l’élimination des radiations, ça pourrait intéresser le marché du moment...', `VerifiedBuild`=25549 WHERE (`ID`=4556 AND `locale`='frFR');
