UPDATE `broadcast_text_locale` SET `MaleText_lang`='Leurs esprits sont maintenant corrompus, $r. Oui, même plus qu’auparavant. Ils ne vivent que pour servir et protéger Razelikh. Les fragments d’amulette que chacun d’entre eux porte sont les clés pour invoquer le seigneur-démon. Ce que vous ne comprenez pas, c’est qu’ils ne peuvent pas être blessés par des moyens conventionnels.', `VerifiedBuild`=25549 WHERE (`ID`=4253 AND `locale`='frFR');
