UPDATE `broadcast_text_locale` SET `MaleText_lang`='Scindée en deux qui forment l’unique. Les lames jumelles sont liées à Zul’Farrak.$B$BSul’thraze renaîtra quand reparaîtront les jumelles.', `VerifiedBuild`=25549 WHERE (`ID`=4184 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Dites-m’en plus, Trenton.', `FemaleText_lang`='Dites-m’en plus, Trenton.', `VerifiedBuild`=25549 WHERE (`ID`=4183 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Sul’thraze... La première fois que j’ai entendu ce mot, j’avais votre âge. Cela ne m’évoquait rien, comme à vous aujourd’hui. Je n’ai compris que lorsqu’une bande de trolls venue de Zul’Farrak dévasta nos terres... Depuis, j’ai peur.$B$BBeaucoup vous diront que la Lame de souffrance n’existe pas. C’est un mythe, une histoire pour faire peur aux enfants. Mais croyez-moi, $r, elle existe.$B$B<Trenton semble se perdre dans ses souvenirs en parcourant du doigt la cicatrice qui le défigure.>', `VerifiedBuild`=25549 WHERE (`ID`=4182 AND `locale`='frFR');
