UPDATE `broadcast_text_locale` SET `MaleText_lang`='Donnez-moi un moment, $n. La situation était tendue ici, il y a peu ; je veux m’assurer que tout est rentré dans l’ordre. Je vous contacte très prochainement.', `VerifiedBuild`=25549 WHERE (`ID`=4102 AND `locale`='frFR');
