UPDATE `broadcast_text_locale` SET `MaleText_lang`='Une armure comme celle que vous avez faite pourrait arrêter la hache la plus lourde. Superbe, $n, je ne vois pas ça tous les jours. Allez trouver une orque nommée Shayis Furie-d’acier ; c’est elle qui fabrique les meilleures armures, hors de cette maudite forteresse.', `VerifiedBuild`=25549 WHERE (`ID`=3959 AND `locale`='frFR');
