UPDATE `broadcast_text_locale` SET `MaleText_lang`='J’aimerais que ce soit vrai, $n, mais vous ne parviendrez pas à combattre les forces de Razelikh et de ses adjoints $gseul:seule;.$B$BRassemblez un groupe adéquat d’aventuriers et de héros en devenir, et libérez mes hommes de leurs tourments éternels ! Dix-huit pierres doivent être brisées.$B$BCombattez sans compter et mourez dans l’honneur, $n.', `VerifiedBuild`=25549 WHERE (`ID`=3711 AND `locale`='frFR');
