UPDATE `broadcast_text_locale` SET `MaleText_lang`='La forme physique |2 %s s’affaiblit. Vous remarquez que la pierre de lien proche de la créature se met à luire : frappez maintenant !', `VerifiedBuild`=25549 WHERE (`ID`=3642 AND `locale`='frFR');
