UPDATE `broadcast_text_locale` SET `MaleText_lang`='Les bêtes des terres Foudroyées sont nanties d’attributs surnaturels, inconnus jusque-là.$B$BNous pensons que l’énergie libérée par l’ouverture de la Porte des ténèbres a irradié leurs corps, les forçant à évoluer jusqu’à leur forme actuelle.$B$BCe sont de cruels animaux mais qu’il serait cependant important d’étudier.$B$BSouhaiteriez-vous nous aider dans l’étude de ces bêtes, $n ?', `VerifiedBuild`=25549 WHERE (`ID`=3521 AND `locale`='frFR');
